/* TRINCA 360 — aplicativo 100% front-end. Dados locais no aparelho. */
(()=>{
'use strict';
const DB=window.TRINCA_DATA;
const ACTIVITY_TYPES=[{"name":"Natação","kind":"cardio","min":45},{"name":"Hidroginástica","kind":"cardio","min":45},{"name":"Caminhada","kind":"cardio","min":30},{"name":"Corrida","kind":"cardio","min":30},{"name":"Esteira","kind":"cardio","min":30},{"name":"Bicicleta ergométrica","kind":"cardio","min":30},{"name":"Ciclismo ao ar livre","kind":"cardio","min":30},{"name":"Elíptico","kind":"cardio","min":30},{"name":"Remo ergométrico","kind":"cardio","min":30},{"name":"Dança aeróbica","kind":"cardio","min":30},{"name":"Pular corda","kind":"cardio","min":20},{"name":"Trilha","kind":"cardio","min":45},{"name":"Escada / simulador","kind":"cardio","min":20},{"name":"Futebol / futsal","kind":"variavel","min":45},{"name":"Basquete","kind":"variavel","min":45},{"name":"Vôlei","kind":"variavel","min":45},{"name":"Tênis","kind":"variavel","min":45},{"name":"Beach tennis","kind":"variavel","min":45},{"name":"Artes marciais","kind":"variavel","min":45},{"name":"Treino funcional","kind":"variavel","min":30},{"name":"Pilates","kind":"bemestar","min":45},{"name":"Yoga","kind":"bemestar","min":45},{"name":"Mobilidade","kind":"bemestar","min":20},{"name":"Alongamento","kind":"bemestar","min":15},{"name":"Outra modalidade","kind":"variavel","min":30}];
const KEY='trinca360-state-v1';
const DEFAULTS={profile:{name:'',age:43,weight:'',height:'',waist:'',experience:'retomando',goal:'definicao',sessionLength:'30',foodStyle:'geral',restrictions:'',startDate:localDate()},sessions:[],measures:[],walks:[],habits:{},drafts:{},hydration:{},reminders:{enabled:false,water:true,snack:true,waterEvery:120,start:'08:00',end:'20:00',snackAM:'10:00',snackPM:'16:00',notifications:false},seenReminders:{},restSound:true,updatedAt:null};
let store=load();
let ui={page:'home',day:'A',selectedExercise:null,sessionSeconds:0,sessionRunning:false,restSeconds:60,restRunning:false,installPrompt:null};
let tickId=null,toastId=null;

let restDeadline=0,restAlertVisible=false,restAlertSoundPlayed=false,restAudioContext=null;
function prepareRestAudio(){
 if(store.restSound===false)return;
 try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!restAudioContext)restAudioContext=new C();if(restAudioContext.state==='suspended')restAudioContext.resume().catch(()=>{});}catch(e){console.warn('Audio de descanso indisponível',e);}
}
async function playRestAlarm(){
 if(restAlertSoundPlayed||document.visibilityState!=='visible')return;
 restAlertSoundPlayed=true;
 if(store.restSound===false)return;
 try{
  prepareRestAudio();const ctx=restAudioContext;if(ctx){if(ctx.state==='suspended')await ctx.resume();const t=ctx.currentTime;
   for(let i=0;i<3;i++){const oscillator=ctx.createOscillator(),gain=ctx.createGain(),start=t+i*.31;oscillator.type='sine';oscillator.frequency.setValueAtTime(i===2?1046:880,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.075,start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+.23);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(start);oscillator.stop(start+.24);}
  }
  if(typeof navigator.vibrate==='function')navigator.vibrate([160,100,160]);
 }catch(e){console.warn('O celular não reproduziu o alerta sonoro',e);}
}
function closeRestAlert(){restAlertVisible=false;restAlertSoundPlayed=false;const root=document.querySelector('#rest-alert-root');if(root)root.innerHTML='';}
function showRestFinished(){
 if(restAlertVisible||ui.page!=='workouts')return;
 restAlertVisible=true;ui.restRunning=false;restDeadline=0;ui.restSeconds=0;
 const root=document.querySelector('#rest-alert-root');if(!root)return;
 root.innerHTML='<div class="rest-full-alert" role="alertdialog" aria-modal="true" aria-labelledby="rest-finish-title" aria-describedby="rest-finish-desc"><div class="rest-alert-inner"><span class="rest-alert-symbol" aria-hidden="true">✓</span><div class="eyebrow">TRINCA 360 · ALERTA DE INTERVALO</div><h2 id="rest-finish-title">DESCANSO CONCLUÍDO!</h2><p id="rest-finish-desc">Seu minuto terminou. Confira sua respiração e a técnica antes da próxima série.</p><div class="rest-alert-buttons"><button type="button" class="btn primary block" data-action="rest-alert-dismiss">Próxima série ✓</button><button type="button" class="btn outline block" data-action="rest-alert-extra">Preciso de +30 segundos</button></div><p class="rest-alert-caption">Você decide quando está recuperado. O aviso aparece enquanto o aplicativo está aberto.</p></div></div>';
 root.querySelector('[data-action="rest-alert-dismiss"]')?.focus();
 playRestAlarm();
}
function stopRest(resetSeconds=true){
 ui.restRunning=false;restDeadline=0;closeRestAlert();if(resetSeconds)ui.restSeconds=60;
}
function startRest(seconds=60){
 closeRestAlert();ui.restSeconds=Math.max(1,Math.ceil(seconds));restDeadline=Date.now()+ui.restSeconds*1000;ui.restRunning=true;prepareRestAudio();render();
}
function pauseRest(){
 if(ui.restRunning){ui.restSeconds=Math.max(0,Math.ceil((restDeadline-Date.now())/1000));ui.restRunning=false;restDeadline=0;}
}
function restSoundMarkup(){return '<div class="rest-sound-row"><button type="button" class="btn ghost smallbtn" data-action="rest-sound-toggle" aria-pressed="'+(store.restSound!==false)+'">'+(store.restSound===false?'🔇 Ativar som do descanso':'🔔 Som do descanso: ligado')+'</button><span class="footnote">Ao marcar uma série, começa um descanso de 60 segundos. O celular pode silenciar áudio ou vibração conforme as configurações.</span></div>';}

const updateState={status:'idle',latest:null,notes:[],checkedAt:null,error:''};
let screenWakeLock=null,screenWakeRequested=false,screenWakePending=false,screenWakeError='';
function screenWakeMarkup(){const supported=typeof navigator.wakeLock?.request==='function',active=!!screenWakeLock&&!screenWakeLock.released;const status=!supported?'Este navegador não oferece a proteção de tela acesa. Consulte o tempo de bloqueio nas configurações do celular.':screenWakePending?'Ativando proteção da tela…':active?'Proteção ativa: a tela ficará acesa durante o treino.':screenWakeRequested?(screenWakeError||'Proteção temporariamente interrompida. Toque para tentar novamente.'):'Proteção desativada: o celular pode apagar a tela normalmente.';return `<section id="screen-wake-panel" class="card wake-card" aria-live="polite"><div class="wake-title"><span class="wake-glyph" aria-hidden="true">☀</span><div><div class="eyebrow">CONFORTO DURANTE O TREINO</div><h3>Tela acesa</h3></div><span class="pill ${active?'':'gray'}">${active?'Ativa':'Inativa'}</span></div><p class="small muted" style="margin:10px 0 12px">${esc(status)}</p><button type="button" class="btn ${active?'outline':'teal'} block" data-action="toggle-screen-wake" ${!supported||screenWakePending?'disabled':''}>${screenWakePending?'Aguarde…':active?'Permitir apagar a tela':screenWakeRequested?'Tentar manter a tela acesa':'Manter tela acesa'}</button><p class="footnote" style="margin:10px 0 0">Ativa ao abrir uma ficha, sem alterar o brilho. Você pode desligar pelo botão acima. Ao finalizar ou sair do treino, a proteção é liberada. O Android pode interrompê-la por bateria, bloqueio manual ou ao colocar o app em segundo plano.</p></section>`}
function refreshScreenWakeUI(){const panel=document.querySelector('#screen-wake-panel');if(panel)panel.outerHTML=screenWakeMarkup();}
async function requestScreenWake(silent=false){if(!screenWakeRequested||ui.page!=='workouts'||document.visibilityState!=='visible')return;if(screenWakeLock&&!screenWakeLock.released)return;if(screenWakePending)return;if(typeof navigator.wakeLock?.request!=='function'){screenWakeRequested=false;screenWakeError='Recurso indisponível neste navegador.';refreshScreenWakeUI();if(!silent)notify('Este navegador não suporta manter a tela acesa.');return;}screenWakePending=true;screenWakeError='';refreshScreenWakeUI();try{const lock=await navigator.wakeLock.request('screen');screenWakePending=false;if(!screenWakeRequested||ui.page!=='workouts'||document.visibilityState!=='visible'){await lock.release();refreshScreenWakeUI();return;}screenWakeLock=lock;lock.addEventListener('release',()=>{if(screenWakeLock===lock)screenWakeLock=null;refreshScreenWakeUI();});if(!silent)notify('Tela protegida: continuará acesa durante o treino.');}catch(error){screenWakePending=false;screenWakeLock=null;screenWakeError='Não foi possível ativar agora. Verifique bateria, navegador e permissões; tente novamente.';if(!silent)notify('Não foi possível impedir o bloqueio da tela neste momento.');}refreshScreenWakeUI();}
function stopScreenWake(silent=false){screenWakeRequested=false;screenWakeError='';const lock=screenWakeLock;screenWakeLock=null;refreshScreenWakeUI();if(lock&&!lock.released)lock.release().catch(()=>{});if(!silent)notify('Proteção desativada: o celular poderá apagar a tela normalmente.');}


const $=sel=>document.querySelector(sel);
const esc=str=>String(str??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtNum=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n);
const fmtDate=iso=>{const p=String(iso||'').split('-').map(Number);if(p.length!==3||!p[0])return '—';return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(p[0],p[1]-1,p[2]));};
function localDate(dt=new Date()){const pad=n=>String(n).padStart(2,'0');return `${dt.getFullYear()}-${pad(dt.getMonth()+1)}-${pad(dt.getDate())}`;}
function localDateFrom(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d);}
function weekStart(dt=new Date()){const d=new Date(dt.getFullYear(),dt.getMonth(),dt.getDate());d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d);}
function dayFor(dt=new Date()){return ({1:'A',3:'B',5:'C'})[dt.getDay()]||null;}
function nextTraining(){const today=new Date(), day=today.getDay();for(let shift=0;shift<8;shift++){const d=new Date(today.getFullYear(),today.getMonth(),today.getDate()+shift), key=dayFor(d);if(key)return {key, date:localDate(d),today:shift===0};}return {key:'A',date:localDate()};}
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&typeof raw==='object'&&Array.isArray(raw.sessions)&&Array.isArray(raw.measures)&&Array.isArray(raw.walks))return {...structuredClone(DEFAULTS),...raw,profile:{...DEFAULTS.profile,...raw.profile},drafts:raw.drafts&&typeof raw.drafts==='object'?raw.drafts:{},habits:raw.habits&&typeof raw.habits==='object'?raw.habits:{},hydration:raw.hydration&&typeof raw.hydration==='object'?raw.hydration:{},reminders:{...DEFAULTS.reminders,...(raw.reminders||{})},seenReminders:raw.seenReminders&&typeof raw.seenReminders==='object'?raw.seenReminders:{}};}catch(e){console.warn('Dados indisponíveis',e);}return structuredClone(DEFAULTS);}
function save(){store.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(store));return true;}catch(e){notify('Armazenamento bloqueado. Exporte um backup para preservar os registros.');return false;}}
function notify(msg){const root=$('#toast-root');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;clearTimeout(toastId);toastId=setTimeout(()=>root.innerHTML='',3300);}
function setNav(page){if(page!=='workouts'){stopRest();if(screenWakeRequested)stopScreenWake(true);}ui.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
function setDay(key){if(ui.day!==key)stopRest();ui.day=key;setNav('workouts');if(!screenWakeRequested){screenWakeRequested=true;requestScreenWake(true);}}
function sessionName(s){if(s.type==='modalidade')return `Atividade · ${esc(s.modality||'Outra modalidade')}`;return s.type==='avulso'||s.day==='AVULSO'?`Treino avulso · ${esc((s.groups||[]).join(' + ')||'Musculação')}`:`Treino ${esc(s.day)} · ${esc((DB.programs[s.day]?.name)||'Musculação')}`;}

function weekNumber(){const start=localDateFrom(store.profile.startDate||localDate());const now=localDateFrom(localDate());return Math.max(1,Math.floor((now-start)/604800000)+1);}
function cycleNumber(){return Math.floor((weekNumber()-1)/12)+1;}
function phaseWeek(){return ((weekNumber()-1)%12)+1;}
function program(day){return (cycleNumber()%2===0?DB.rotations:DB.programs)[day];}
// O calendario sozinho nao libera o aumento de volume para iniciantes/retomando.
function adaptationCompletedDays(){const start=store.profile.startDate||localDate();return new Set(store.sessions.filter(s=>['A','B','C'].includes(s.day)&&s.date>=start&&s.partial===false&&Number(s.doneSets)>0).map(s=>s.date)).size;}
function adaptationPending(){return cycleNumber()===1&&store.profile.experience!=='ativo'&&phaseWeek()>2&&adaptationCompletedDays()<3;}
function prescriptionWeek(){return adaptationPending()?2:phaseWeek();}
function mainSets(){if(prescriptionWeek()<=2&&store.profile.experience!=='ativo')return 1;return store.profile.sessionLength==='60'?4:store.profile.sessionLength==='45'?4:3;}
function setsFor(day,id){if(prescriptionWeek()<=2&&store.profile.experience!=='ativo')return 1;return store.profile.sessionLength==='60'?4:(program(day).exercises[0]===id?mainSets():(store.profile.sessionLength==='45'?3:2));}
function repFor(id){const r=DB.exercises[id].reps;if(/(?:\bs\b|lado|perna)/i.test(r))return r;return prescriptionWeek()<=6?'10–12':prescriptionWeek()<=10?'8–10':'10–12';}
function rirGoal(){const w=prescriptionWeek();return w<=2?'3–4':w<=6?'2–3':w<=10?'1–2':'3–4';}
function restGoal(){return store.profile.sessionLength==='60'?'60–120 s':store.profile.sessionLength==='45'?'60–90 s':'45–75 s';}
function phaseTitle(){const x=prescriptionWeek();return DB.phases[x<=2?0:x<=6?1:x<=10?2:3];}
function progressionNotice(){if(adaptationPending())return `Adaptação mantida: ${adaptationCompletedDays()}/3 dias com ficha A/B/C completa desde o início do programa. O calendário avançou, mas o volume só aumentará após três dias completos. Treinos avulsos e sessões parciais entram no histórico, mas não destravam esta etapa.`;if(prescriptionWeek()<=2&&store.profile.experience!=='ativo')return `Adaptação inicial: 1 série por exercício nas semanas 1–2. A partir da 3ª semana, o volume pode subir se houver ao menos 3 dias distintos com ficha A/B/C integralmente concluída (atual: ${adaptationCompletedDays()}/3).`;return 'Seu plano ajusta séries e faixas de repetição conforme fase e duração. A carga nunca sobe sozinha: registre desempenho e confirme os ajustes com o instrutor.';}
function repsCeiling(label){const values=String(label||'').match(/\d+/g);return values?Number(values[values.length-1]):0;}
function nextLoadHint(day,id){
 const past=[...store.sessions].reverse().filter(s=>s.exercises&&s.exercises[id]&&Number(s.exercises[id].weight)>0);
 if(!past.length)return 'Comece com carga confortável e refine a técnica. Registre o menor número de repetições, RIR e execução para acompanhar a evolução.';
 const last=past[0].exercises[id],load=Number(last.weight),previous=past[1]?.exercises?.[id];
 if(last.technique==='ajustar')return `Última carga: ${esc(last.weight)} kg. Você marcou que a técnica precisa de ajuste; não aumente a carga e peça orientação.`;
 if(last.rir!=null&&Number(last.rir)<=1)return `Última carga: ${esc(last.weight)} kg, com pouco esforço em reserva (RIR ${esc(last.rir)}). Mantenha ou reduza a carga para recuperar a execução.`;
 if(/(?:\bs\b|segundo)/i.test(DB.exercises[id].reps))return 'Para exercícios de tempo, progrida duração e controle com orientação, sem aumento automático.';
 const qualified=r=>!!r&&Number(r.weight)===load&&Number(r.setsDone)>=Number(r.planned)&&Number(r.repsDone)>=repsCeiling(r.reps)&&Number(r.rir)>=2&&Number(r.rir)<=4&&r.technique==='boa';
 if(qualified(last)&&qualified(previous))return `Últimas duas sessões com ${esc(last.weight)} kg: todas as séries, meta de repetições, RIR 2–4 e boa execução registrados. No próximo treino, avalie com o instrutor um aumento pequeno (2–5%); nunca é aplicado automaticamente.`;
 if(last.repsDone==null||last.rir==null||!last.technique)return `Última carga: ${esc(last.weight)} kg. Preencha repetições reais, RIR e execução para liberar uma sugestão fundamentada de progressão.`;
 return `Última carga: ${esc(last.weight)} kg. Mantenha e consolide a meta com boa técnica em duas sessões antes de considerar aumento.`;
}

function draftFor(day){if(!store.drafts[day]||typeof store.drafts[day]!=='object')store.drafts[day]={};const obj=store.drafts[day];for(const exId of program(day).exercises){if(!obj[exId]||!Array.isArray(obj[exId].sets))obj[exId]={sets:[],weight:'',rir:''};}return obj;}
function completedSets(day){const d=draftFor(day);let count=0;for(const id of program(day).exercises)count+=d[id].sets.slice(0,setsFor(day,id)).filter(Boolean).length;return count;}
function targetSets(day){return program(day).exercises.reduce((a,id)=>a+setsFor(day,id),0);}
function sessionsThisWeek(){const w=weekStart(),today=localDate();return store.sessions.filter(s=>s.date>=w&&s.date<=today);}
function strengthThisWeek(){return sessionsThisWeek().filter(s=>s.type!=='modalidade');}
function modalitiesThisWeek(){return sessionsThisWeek().filter(s=>s.type==='modalidade');}
function cardioThisWeek(){const w=weekStart();return sessionsThisWeek().reduce((acc,s)=>acc+(Number(s.cardioMin)||0),0)+store.walks.filter(walk=>walk.date>=w).reduce((acc,s)=>acc+(Number(s.minutes)||0),0);}
function titleBlock(eye,title,sub){return `<div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p class="muted small">${sub}</p>`:''}`;}
function commonNotice(){return `<div class="notice warning"><span style="font-size:19px">⚕</span><div>Adapte o exercício à sua condição e aos aparelhos disponíveis. Se houver doença relevante, dor persistente ou longo período de sedentarismo, procure orientação de profissional habilitado. Pare diante de dor no peito, tontura ou falta de ar incomum.</div></div>`;}
// O controle de versao e separado do historico do usuario (localStorage).
function versionParts(value){return String(value||'0.0.0').split('.').map(x=>Number(x)||0);}
function isVersionNewer(remote,local){const a=versionParts(remote),b=versionParts(local);for(let i=0;i<3;i++){if((a[i]||0)!==(b[i]||0))return (a[i]||0)>(b[i]||0);}return false;}
function updatesMarkup(){const current=esc(DB.version),newer=updateState.status==='available',latest=esc(updateState.latest||'');let msg='Toque para consultar a versão publicada. Seus treinos e medidas não são apagados por uma atualização normal.';
if(updateState.status==='checking')msg='Consultando a versão mais recente…';
if(updateState.status==='current')msg='Você já está usando a versão mais recente disponível.';
if(newer)msg=`Nova versão ${latest} disponível! Confira as novidades e aplique quando terminar sua sessão.`;
if(updateState.status==='offline')msg='Sem internet no momento. Seus treinos salvos continuam disponíveis; tente novamente quando conectar.';
if(updateState.status==='error')msg=updateState.error||'Não foi possível verificar agora. Tente novamente.';
if(updateState.status==='applying')msg='Preparando a versão nova. Mantenha a conexão até o reinício.';
return `<div id="update-status-panel" class="card update-panel" aria-live="polite"><div class="update-heading"><div><div class="eyebrow">VERSÃO DO APLICATIVO</div><h3 style="margin:0">TRINCA 360 · v${current}</h3></div><span class="pill ${newer?'gold':'blue'}">${newer?'Nova versão':'Instalado'}</span></div><p class="small muted" style="margin:11px 0">${msg}</p>${newer&&updateState.notes.length?`<ul class="tip-list">${updateState.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}<div class="update-buttons"><button type="button" class="btn outline block" data-action="check-updates" ${['checking','applying'].includes(updateState.status)?'disabled':''}>↻ ${updateState.status==='checking'?'Verificando…':'Verificar atualizações'}</button>${newer?'<button type="button" class="btn teal block" data-action="apply-update">Aplicar atualização</button>':''}</div><p class="footnote" style="margin:10px 0 0">Não é necessário desinstalar o aplicativo. Antes de atualizar, finalize o treino em andamento e mantenha um backup periódico em Perfil.</p></div>`;}
function refreshUpdatePanel(){const panel=$('#update-status-panel');if(panel)panel.outerHTML=updatesMarkup();}
async function checkForUpdates(manual=true){if(updateState.status==='checking'||updateState.status==='applying')return;
 updateState.status='checking';updateState.error='';refreshUpdatePanel();
 try{
  const url=new URL('./version.json',document.baseURI);url.searchParams.set('consulta',String(Date.now()));
  const response=await fetch(url.toString(),{cache:'no-store',headers:{'Accept':'application/json'}});
  if(!response.ok)throw new Error('Servidor indisponível');
  const info=await response.json();const latest=String(info.version||'');
  if(!/^\d+\.\d+\.\d+$/.test(latest))throw new Error('Versão não reconhecida');
  updateState.latest=latest;updateState.notes=Array.isArray(info.notes)?info.notes.filter(n=>typeof n==='string').slice(0,4):[];
  updateState.checkedAt=new Date().toISOString();
  updateState.status=isVersionNewer(latest,DB.version)?'available':'current';
  if(updateState.status==='available'&&'serviceWorker' in navigator){navigator.serviceWorker.getRegistration().then(reg=>reg?.update()).catch(()=>{});}
  refreshUpdatePanel();if(manual)notify(updateState.status==='available'?`Nova versão ${latest} encontrada!`:'Seu aplicativo está atualizado.');
 }catch(error){updateState.status=navigator.onLine?'error':'offline';updateState.error='Não foi possível consultar a versão no momento.';refreshUpdatePanel();if(manual)notify(updateState.status==='offline'?'Conecte-se à internet para verificar.':'Não foi possível verificar agora.');}
}
async function applyAppUpdate(){if(updateState.status!=='available')return;
 if(!window.confirm('O aplicativo será reiniciado. Finalize ou salve o treino em andamento antes de continuar. Seus registros já salvos serão preservados. Aplicar atualização?'))return;
 if(!navigator.onLine){updateState.status='offline';refreshUpdatePanel();notify('Conecte-se à internet para atualizar.');return;}
 if(!save())return;
 updateState.status='applying';refreshUpdatePanel();
 try{
  if('serviceWorker' in navigator){const registration=await navigator.serviceWorker.getRegistration();if(registration){
   const old=navigator.serviceWorker.controller;await registration.update();
   if(registration.waiting)registration.waiting.postMessage({type:'SKIP_WAITING'});
   if(old===navigator.serviceWorker.controller&&(registration.installing||registration.waiting))await new Promise(resolve=>{
    let finished=false;let timer;const done=()=>{if(finished)return;finished=true;clearTimeout(timer);navigator.serviceWorker.removeEventListener('controllerchange',done);resolve();};
    navigator.serviceWorker.addEventListener('controllerchange',done);timer=setTimeout(done,9000);
    if(old!==navigator.serviceWorker.controller)done();
   });
  }}
  const url=new URL('./index.html',document.baseURI);url.searchParams.set('versao',updateState.latest||String(Date.now()));window.location.replace(url.toString());
 }catch(error){updateState.status='available';refreshUpdatePanel();notify('Não foi possível aplicar agora. Verifique sua conexão e tente novamente.');}
}

function home(){const next=nextTraining(),plan=program(next.key),week=strengthThisWeek(),activities=modalitiesThisWeek(),min=cardioThisWeek(),name=store.profile.name?`Olá, ${esc(store.profile.name.split(' ')[0])}!`:'Seu treino, seu ritmo.';return `
  <section class="hero"><div class="eyebrow">SEU PROJETO DE EVOLUÇÃO</div><h1>${name}<br>Corpo forte.<br>Rotina possível.</h1><p class="subtitle">3 treinos por semana · ${store.profile.sessionLength} minutos por sessão · evolução real, sem promessas mágicas.</p><button class="btn primary cta" data-action="open-day" data-day="${next.key}">Começar treino ${next.key} <span aria-hidden="true">↗</span></button></section>
  <div class="quick-actions"><button class="btn outline" data-action="go-help">❔ Manual e ajuda</button><button class="btn outline" data-action="go-avulso">＋ Treino avulso</button><button class="btn outline" data-action="go-updates">↻ Atualizações</button></div>
  <div class="measure-shortcut"><div><strong>📏 Minhas medidas corporais</strong><p>Registre cintura, glúteos, braços e coxas. Compare sua evolução em centímetros.</p></div><button class="btn teal block" data-action="go-measure">Registrar minhas medidas →</button></div>
  <div class="grid-two spaced"><div class="metric"><div class="mini-icon">✦</div><div class="number">${week.length}<span style="font-size:13px;color:var(--muted)"> / 3</span></div><div class="label">Sessões de força nesta semana (fichas e musculação avulsa)</div></div><div class="metric"><div class="mini-icon">◷</div><div class="number">${min}<span style="font-size:13px;color:var(--muted)"> min</span></div><div class="label">Cardio registrado na semana</div></div></div>
  <p class="footnote" style="margin:8px 0 15px">${activities.length?`${activities.length} atividade(s) de outras modalidades nesta semana (como natação).`:'Natação e outras modalidades também podem ser registradas em Treino avulso.'}</p>
  <div class="section-heading"><h2>Próximo treino</h2><span class="badge-date">${next.today?'Hoje':fmtDate(next.date)}</span></div>
  ${dayCard(next.key,true)}
  <div class="section-heading"><h2>Seu plano semanal</h2><button class="link-btn" data-action="go-workouts">Ver treinos →</button></div>
  <div class="stack">${['A','B','C'].map(k=>dayCard(k,false)).join('')}</div>
  <div class="section-heading"><h2>Distribuição do tempo</h2></div><div class="card flat"><div class="timeline"><div></div><div></div><div></div><div></div></div><div class="time-parts"><div><strong>${store.profile.sessionLength==='30'?4:5} min</strong><span>Aquecimento</span></div><div><strong>${store.profile.sessionLength==='30'?20:store.profile.sessionLength==='45'?32:45} min</strong><span>Musculação</span></div><div><strong>${store.profile.sessionLength==='30'?4:store.profile.sessionLength==='45'?6:8} min</strong><span>Cardio</span></div><div><strong>2 min</strong><span>Recuperação</span></div></div><p class="footnote" style="margin:13px 0 0">Os 4 minutos de cardio por treino são um ponto de partida e não substituem a recomendação semanal de atividade aeróbica.</p></div>
  <div class="section-heading"><h2>Seu ciclo evolutivo</h2></div><div class="next-banner"><div class="eyebrow">CICLO ${cycleNumber()} · SEMANA ${phaseWeek()} DE 12</div><strong>${phaseTitle().title}</strong><p class="small muted" style="margin:7px 0 0">${phaseTitle().body} ${progressionNotice()} Na semana 13 inicia uma rotação de exercícios. Confirme suas condições com um profissional antes de aumentar cargas.</p><div class="pill-row" style="margin-top:10px"><span class="pill">${store.profile.sessionLength} min</span><span class="pill blue">Esforço-alvo: RIR ${rirGoal()}</span></div></div>
  <div class="section-heading"><h2>Minha avaliação</h2><button class="link-btn" data-action="go-measure">Registrar medidas →</button></div>${assessmentCard()}${bodyAssessmentTeaser()}
  <p class="footnote" style="margin:10px 0 0">${goalAdvice()}</p><div class="section-heading"><h2>Hidratação hoje</h2><button class="link-btn" data-action="go-nutrition">Registrar água →</button></div>${waterCard()}
  <div class="section-heading"><h2>Treino com evidência</h2></div><div class="notice"><span style="font-size:22px">✓</span><div>Programa baseado em princípios de instituições de referência como ACSM, OMS e Ministério da Saúde. <button class="link-btn" data-action="go-nutrition" style="display:block;text-align:left;margin-top:2px">Ver orientações e fontes →</button></div></div>`;}
function dayCard(key,highlight=false){const p=program(key),records=sessionsThisWeek().filter(s=>s.day===key);return `<button class="day-card ${highlight?'selected':''}" data-action="open-day" data-day="${key}" style="text-align:left;width:100%"><div class="day-icon" style="background:${p.accent}"><small>TREINO</small>${key}</div><div class="data"><h3>${p.name}</h3><p>${p.subtitle}</p><div class="pill-row"><span class="mini-tag">${p.day}</span><span class="mini-tag">${store.profile.sessionLength} min</span>${records.length?'<span class="pill" style="padding:4px 7px">✓ feito</span>':''}</div></div><span class="arrow">›</span></button>`;}
function workoutPage(){const day=ui.day,p=program(day),d=draftFor(day),target=targetSets(day),done=completedSets(day),pct=done/target*100;return `
  <div class="eyebrow">CICLO ${cycleNumber()} · SEMANA ${phaseWeek()} DE 12</div><h1>Vamos treinar.</h1><div class="tab-row">${Object.keys(DB.programs).map(k=>`<button class="tab-pill ${day===k?'active':''}" data-action="open-day" data-day="${k}">Treino ${k}</button>`).join('')}</div>
  <section class="program-banner" style="background:${p.accent}"><div class="top-info"><span class="pill dark">${p.day}</span><span class="pill dark">${store.profile.sessionLength} min</span></div><h1>Treino ${day} · ${p.name}</h1><p>${p.subtitle}</p></section>
  <div class="section-heading"><h2>Prescrição de hoje</h2><span class="badge-date">${done}/${target} séries</span></div>
  <div class="card flat"><div class="pill-row"><span class="pill blue">${phaseTitle().title}</span><span class="pill">RIR ${rirGoal()}</span><span class="pill gray">Pausa ${restGoal()}</span></div><div class="progress-track"><div style="width:${pct}%"></div></div><p class="small muted" style="margin:11px 0 0">${goalAdvice()} RIR = repetições que você ainda conseguiria fazer ao final da série. RIR 2 significa parar com cerca de 2 repetições possíveis. Nunca priorize carga acima da técnica.</p><p class="footnote" style="margin:10px 0 0"><strong>Evolução programada:</strong> ${progressionNotice()}</p><p class="footnote"><strong>Check-in corporal:</strong> ${bodyMeasureFollowup()} As medidas ajudam a avaliar seus resultados, mas não alteram automaticamente as séries.</p>${store.profile.sessionLength==='30'?'<p class="footnote">Modo 30 min: 3 séries no movimento principal e 2 nos demais (exceto adaptação inicial). Para 4 séries principais e 3 auxiliares, escolha 45 min; para até 4 em todos, escolha 60 min.</p>':'<p class="footnote">Modo estendido: consulte a quantidade de séries exibida em cada cartão; ajuste as pausas ao seu fôlego.</p>'}</div>
  ${screenWakeMarkup()}
  <div class="section-heading"><h2>Relógios do treino</h2></div><div class="timer-panel"><div class="timer-box"><p>⏱ Sessão</p><div id="clock-session" class="time">${toClock(ui.sessionSeconds)}</div><div class="timer-controls"><button data-action="session-toggle">${ui.sessionRunning?'Pausar':'Iniciar'}</button><button class="secondary" data-action="session-reset">↺</button></div></div><div class="timer-box"><p>◷ Intervalo</p><div id="clock-rest" class="time">${toClock(ui.restSeconds)}</div><div class="timer-controls"><button data-action="rest-toggle">${ui.restRunning?'Pausar':ui.restSeconds===60?'Iniciar':'Retomar'}</button><button class="secondary" data-action="rest-reset">↺</button></div></div></div>${restSoundMarkup()}
  <div class="section-heading"><h2>Exercícios e metas</h2><span class="muted small">Toque em “Como fazer”</span></div>
  ${p.exercises.map((id,i)=>exerciseCard(day,id,i)).join('')}
  <div class="card"><h3>Fechar sessão</h3><p class="small muted">Marque as séries efetivamente realizadas. Registre carga e RIR para apoiar a próxima sessão.</p><button class="btn teal block" data-action="finish-start" data-day="${day}">Registrar este treino ✓</button></div>
  <div style="margin-top:13px">${commonNotice()}</div>`;}
function exerciseCard(day,id,i){const ex=DB.exercises[id],draft=draftFor(day)[id],n=setsFor(day,id),done=draft.sets.slice(0,n).filter(Boolean).length;return `<article class="exercise-item"><div class="exercise-main"><img loading="lazy" class="exercise-img" src="assets/exercises/${ex.image}.svg" alt="Ilustração esquemática de ${esc(ex.name)}"><div class="exercise-content"><div class="eyebrow" style="margin:0;font-size:9px">${String(i+1).padStart(2,'0')} · ${esc(ex.group)} ${i===0?'· PRINCIPAL':''}</div><h3>${esc(ex.name)}</h3><div class="subtitle">${esc(ex.equipment)}</div><div class="exercise-meta"><span class="mini-tag emphasis">${n} ${n===1?'série':'séries'} × ${esc(repFor(id))}</span><span class="mini-tag">${done}/${n} feitas</span></div></div></div><div class="exercise-tools"><div class="set-dots">${Array.from({length:n},(_,j)=>`<button class="set-btn ${draft.sets[j]?'done':''}" data-action="set-toggle" data-day="${day}" data-id="${id}" data-index="${j}" aria-pressed="${!!draft.sets[j]}" aria-label="Marcar série ${j+1} de ${esc(ex.name)}">${draft.sets[j]?'✓':'S'+(j+1)}</button>`).join('')}</div><div class="exercise-actions"><button class="btn ghost smallbtn" data-action="exercise-detail" data-id="${id}" data-day="${day}">▶ Como fazer</button></div></div><div class="grid-two" style="margin-top:12px"><label class="mini-field">Carga (kg)<input aria-label="Carga de ${esc(ex.name)} em quilogramas" data-input="weight" data-day="${day}" data-id="${id}" type="number" min="0" max="500" step="0.5" value="${esc(draft.weight||'')}" placeholder="kg" inputmode="decimal"></label><label class="mini-field">RIR real da última série<select aria-label="RIR real de ${esc(ex.name)}" data-input="rir" data-day="${day}" data-id="${id}"><option value="" ${draft.rir===''?'selected':''}>Escolher</option>${[0,1,2,3,4,5].map(v=>`<option value="${v}" ${String(draft.rir)===String(v)?'selected':''}>${v}${v===5?'+':''}</option>`).join('')}</select></label></div><div class="grid-two" style="margin-top:10px"><label class="mini-field">Menor resultado por série (reps ou segundos; por lado quando indicado)<input aria-label="Menor desempenho de ${esc(ex.name)}" data-input="reps-done" data-day="${day}" data-id="${id}" type="number" min="1" max="90" step="1" value="${esc(draft.repsDone||'')}" placeholder="Valor real" inputmode="numeric"></label><label class="mini-field">Qualidade da execução<select aria-label="Execução de ${esc(ex.name)}" data-input="technique" data-day="${day}" data-id="${id}"><option value="" ${!draft.technique?'selected':''}>Escolher</option><option value="boa" ${draft.technique==='boa'?'selected':''}>Boa, controlada</option><option value="ajustar" ${draft.technique==='ajustar'?'selected':''}>Precisa ajustar</option></select></label></div><p class="footnote" style="margin:10px 0 0">${nextLoadHint(day,id)}</p></article>`;}

function workoutListPage(){return `${titleBlock('TREINAMENTO','Seus três treinos.','Segunda, quarta e sexta: escolha uma sessão e avance no seu ritmo.')}<div class="card flat"><h3>Treinou fora da ficha A/B/C?</h3><p class="small muted">Registre musculação extra (peito + bíceps) ou outra modalidade, como natação de 45 minutos. O app separa atividades aeróbicas de sessões de força e não marca fichas A/B/C indevidamente.</p><button class="btn teal block" data-action="go-avulso">＋ Registrar treino avulso</button></div><div class="section-heading"><h2>Fichas planejadas</h2></div><div class="stack">${Object.keys(DB.programs).map(k=>dayCard(k)).join('')}</div><div class="section-heading"><h2>Progressão em 12 semanas</h2></div><div class="stack">${DB.phases.map((p,i)=>`<div class="card flat"><div class="pill ${(i===0?prescriptionWeek()<=2:i===1?prescriptionWeek()>=3&&prescriptionWeek()<=6:i===2?prescriptionWeek()>=7&&prescriptionWeek()<=10:prescriptionWeek()>=11)?'blue':'gray'}">Semanas ${p.weeks}</div><h3 style="margin:10px 0 7px">${p.title}</h3><p class="small muted" style="margin:0">${p.body}</p></div>`).join('')}</div>`;}
function modalityForm(){const opt=ACTIVITY_TYPES.map(x=>`<option value="${esc(x.name)}" data-kind="${x.kind}" data-duration="${x.min}">${esc(x.name)}</option>`).join('');return `<div class="modality-panel card"><div class="eyebrow">NATAÇÃO E OUTRAS ATIVIDADES</div><h2>Registre sua modalidade.</h2><p class="small muted">Natação já vem preenchida com <strong>45 min</strong>. Você pode registrar aos sábados e também em qualquer outro dia, sempre com a data e a duração realmente realizadas.</p><form id="modality-form"><div class="form-field"><label for="mod-date">Data da atividade</label><input id="mod-date" name="date" type="date" max="${localDate()}" value="${localDate()}" required></div><div class="form-field"><label for="mod-kind">Modalidade</label><select id="mod-kind" name="modality" required>${opt}</select></div><div class="form-field" id="mod-other-wrap" hidden><label for="mod-other">Qual modalidade?</label><input id="mod-other" type="text" name="other" maxlength="55" placeholder="Escreva o nome da atividade"></div><div class="grid-two"><div class="form-field"><label for="mod-duration">Duração real (min)</label><input id="mod-duration" name="duration" type="number" min="1" max="600" step="1" value="45" required></div><div class="form-field"><label for="mod-cardio">Minutos aeróbicos realizados</label><input id="mod-cardio" name="cardio" type="number" min="0" max="600" step="1" value="45" data-auto="yes" required></div></div><p class="footnote">Na natação e nas modalidades aeróbicas, o app sugere os mesmos minutos da duração. Ajuste se houve pausas. Para esportes intermitentes, yoga, Pilates e outras modalidades, informe somente os minutos aeróbicos que souber identificar. Isso não estima calorias nem intensidade automaticamente.</p><div class="form-field"><label for="mod-effort">Como foi o esforço? (opcional)</label><select id="mod-effort" name="effort"><option value="Não informado">Prefiro não informar</option><option value="Leve">Leve — confortável</option><option value="Moderado">Moderado — respiração mais rápida</option><option value="Vigoroso">Vigoroso — difícil manter uma conversa</option></select></div><div class="form-field"><label for="mod-note">Observações (opcional)</label><textarea id="mod-note" name="note" maxlength="300" placeholder="Ex.: piscina, nado livre; fiz intervalos; como me senti"></textarea></div><button class="btn teal block" type="submit">✓ Salvar atividade</button></form><p class="footnote" style="margin-top:10px">A atividade aparece no histórico e na frequência geral. Só a musculação conta na meta de força. Não lance novamente os mesmos minutos em Cardio extra.</p></div>`;}
function syncModalityForm(resetDuration=false){const select=document.querySelector('#mod-kind'),time=document.querySelector('#mod-duration'),cardio=document.querySelector('#mod-cardio'),other=document.querySelector('#mod-other'),wrap=document.querySelector('#mod-other-wrap');if(!select||!time||!cardio)return;const a=ACTIVITY_TYPES.find(v=>v.name===select.value);if(!a)return;if(resetDuration)time.value=String(a.min);if(wrap)wrap.hidden=select.value!=='Outra modalidade';if(other)other.required=select.value==='Outra modalidade';if(cardio.dataset.auto==='yes'||resetDuration){cardio.value=String(a.kind==='cardio'?time.value:0);cardio.dataset.auto='yes';}}
function avulsoPage(){return `${titleBlock('REGISTRO LIVRE','Treino avulso.','Registre uma sessão que você realmente realizou fora das fichas A, B ou C.')}
  ${modalityForm()}
  <div class="section-heading"><h2>Musculação fora das fichas A/B/C</h2></div>
  <div class="notice info"><span>✓</span><div>Exemplo: peito + bíceps e 10 minutos de esteira = <strong>1 sessão de força + 10 minutos de cardio</strong>. A musculação será contabilizada nas sessões da semana, sem marcar uma ficha planejada como concluída. Registre cada minuto de cardio apenas uma vez.</div></div>
  <div class="card" style="margin-top:14px"><form id="avulso-form"><div class="form-field"><label for="av-date">Data em que treinou</label><input id="av-date" type="date" name="date" max="${localDate()}" value="${localDate()}" required></div><div class="form-field"><label>Quais grupos musculares trabalhou? (marque pelo menos um)</label><div class="group-choices">${['Peito','Costas','Bíceps','Tríceps','Pernas','Ombros','Abdômen','Glúteos','Corpo inteiro','Outro'].map(g=>`<label class="group-choice"><input type="checkbox" name="groups" value="${g}"> ${g}</label>`).join('')}</div></div><div class="grid-two"><div class="form-field"><label for="av-strength">Musculação (min)</label><input id="av-strength" name="strength" type="number" min="1" max="300" step="1" placeholder="Ex.: 25" required></div><div class="form-field"><label for="av-cardio">Cardio na mesma sessão (min)</label><input id="av-cardio" name="cardio" type="number" min="0" max="300" step="1" value="0" required></div></div><div class="form-field"><label for="av-cardio-kind">Tipo de cardio (se houver)</label><select id="av-cardio-kind" name="cardioType"><option>Esteira</option><option>Caminhada ao ar livre</option><option>Bicicleta</option><option>Elíptico</option><option>Natação</option><option>Corrida</option><option>Hidroginástica</option><option>Remo</option><option>Outro</option></select></div><div class="form-field"><label for="av-note">Exercícios, séries e observações (opcional)</label><textarea id="av-note" name="note" maxlength="300" placeholder="Ex.: Supino 3 × 10; rosca bíceps 3 × 12; esteira 10 min"></textarea></div><p class="footnote">Informe o tempo real, não o planejado. Se incluiu a esteira aqui, NÃO a registre novamente em Cardio extra.</p><button class="btn teal block" type="submit">✓ Salvar treino avulso</button></form></div><button class="btn outline block" style="margin-top:12px" data-action="go-progress">Ver meu histórico →</button><div style="margin-top:13px">${commonNotice()}</div>`;}

function progressPage(){const total=store.sessions.length,forceTotal=store.sessions.filter(s=>s.type!=='modalidade').length,min=cardioThisWeek(),allSessions=[...store.sessions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);return `
  ${titleBlock('SEUS RESULTADOS','Evolução que se vê.','Seu diário particular de consistência, cargas e medidas.')}<div class="measure-top-action"><strong>📏 Avaliação corporal</strong><p>Registre agora: cintura, glúteos, braços direito/esquerdo e coxas direita/esquerda.</p><button type="button" class="btn teal block" data-action="scroll-measure">Abrir ficha de medidas ↓</button></div><div class="grid-two"><div class="metric"><div class="mini-icon">🏋</div><div class="number">${total}</div><div class="label">Atividades registradas (força: ${forceTotal})</div></div><div class="metric"><div class="mini-icon">⚡</div><div class="number">${min} <span style="font-size:12px">min</span></div><div class="label">Cardio nesta semana</div></div></div>
  <div class="section-heading"><h2>Fiz outro treino na academia</h2></div><div class="card flat"><p class="small muted">Registre peito + bíceps, natação de 45 minutos, corrida, ciclismo, Pilates e outras modalidades. Cada atividade fica identificada corretamente.</p><button class="btn teal block" data-action="go-avulso">＋ Registrar treino avulso</button></div>
  <div class="section-heading"><h2>Últimas 8 semanas</h2></div><div class="card"><div class="pill-row"><span class="pill">Referência de força: 3 sessões / semana</span></div>${weeklyBars()}<p class="footnote" style="margin-bottom:0">Cada barra mostra as atividades registradas (inclui natação e outras modalidades). A meta de força é contabilizada separadamente no Início.</p></div>
  <div class="section-heading"><h2>Caminhadas e cardio extra</h2></div><div class="card"><p class="footnote">Use esta área apenas para cardio independente. Se os minutos já estão dentro de uma sessão A/B/C ou avulsa, não repita o lançamento.</p><form id="walk-form"><div class="grid-two"><div class="form-field"><label for="walk-date">Data</label><input id="walk-date" name="date" type="date" max="${localDate()}" required value="${localDate()}"></div><div class="form-field"><label for="walk-min">Minutos realizados</label><input id="walk-min" name="minutes" type="number" min="1" max="600" placeholder="Ex.: 20" required></div></div><div class="form-field"><label for="walk-kind">Atividade</label><select name="type" id="walk-kind"><option>Esteira</option><option>Caminhada ao ar livre</option><option>Bicicleta</option><option>Elíptico</option><option>Outro</option></select></div><button class="btn teal block" type="submit">+ Registrar cardio independente</button></form>${cardioHistory()}<p class="footnote" style="margin:13px 0 0">A OMS recomenda cerca de 150–300 min/semana de atividade aeróbica moderada para adultos, além da força. O registro não mede intensidade.</p></div>
  <div class="section-heading"><h2>Avaliação atual</h2></div>${assessmentCard()}
  <div id="measure-section" class="section-heading"><h2>Avaliação corporal</h2></div><div class="card"><p class="small muted">Registre sua medida inicial e repita, se desejar, aproximadamente a cada quatro semanas. Braços e coxas são medidos separadamente (direito e esquerdo); glúteos correspondem à maior circunferência ao redor do quadril. Tudo é opcional.</p><form id="measure-form"><div class="form-field"><label for="measure-date">Data da avaliação</label><input id="measure-date" type="date" name="date" max="${localDate()}" required value="${localDate()}"></div><div class="grid-two">${BODY_FIELDS.map(f=>bodyFieldInput(f,bodyMeasureValues())).join('')}</div><p class="footnote">Ao selecionar uma data já cadastrada, seus valores reaparecem para edição. Medidas não ajustam automaticamente séries ou cargas.</p><button type="submit" class="btn teal block">Salvar avaliação corporal</button></form>${bodyAssessmentMarkup()}<div id="measure-history">${measureHistory()}</div>${measurementTrends()}</div>
  <div class="section-heading"><h2>Histórico de treinos</h2></div><div class="card">${allSessions.length?allSessions.map(s=>`<div class="history-row"><div class="pill-row"><div class="history-icon">✓</div><div><strong>${sessionName(s)}</strong><span>${fmtDate(s.date)} · ${esc(s.durationMin)} min ${s.type==='modalidade'?`· aeróbico ${esc(s.cardioMin||0)} min · esforço ${esc(s.effort||'Não informado')}`:s.type==='avulso'?`(força ${esc(s.strengthMin)} + cardio ${esc(s.cardioMin)})`:`· ${esc(s.doneSets)} séries · cardio ${esc(s.cardioMin||0)} min`}${s.note?` · ${esc(s.note)}`:''}</span></div></div><span class="status ${s.partial?'partial':'ok'}">${s.type==='modalidade'?'Atividade':s.type==='avulso'?'Avulso':s.partial?'Parcial':'Feito'}</span></div>`).join(''):`<div class="empty">Seu primeiro treino registrado aparecerá aqui. 💪</div>`}</div>`;}
function cardioHistory(){const arr=[...store.walks].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return arr.length?`<div class="extra-cardio-history"><div class="eyebrow">CARDIO INDEPENDENTE · REGISTROS RECENTES</div>${arr.map(w=>`<div class="history-row"><div><strong>${esc(w.type||'Caminhada / cardio')}</strong><span>${fmtDate(w.date)} · ${esc(w.minutes)} minutos</span></div><button class="btn ghost smallbtn" data-action="remove-cardio" data-id="${esc(w.id)}">Excluir</button></div>`).join('')}</div>`:'';}
function weeklyBars(){const monday=localDateFrom(weekStart());const series=[];for(let i=7;i>=0;i--){const start=new Date(monday);start.setDate(start.getDate()-i*7);const iso=localDate(start);const count=store.sessions.filter(s=>weekStart(localDateFrom(s.date))===iso).length;series.push({count,lab:fmtDate(iso)});}const high=Math.max(3,...series.map(s=>s.count));return `<div class="bars">${series.map(v=>`<div class="bar-col"><strong>${v.count||'·'}</strong><div class="bar" style="height:${Math.max(4,v.count/high*90)}px"></div><span>${v.lab}</span></div>`).join('')}</div>`;}
const BODY_FIELDS=[
 {key:'weight',label:'Peso',unit:'kg',min:20,max:350},
 {key:'waist',label:'Cintura',unit:'cm',min:30,max:220},
 {key:'hips',label:'Glúteos / quadril',unit:'cm',min:30,max:240},
 {key:'armRight',label:'Braço direito',unit:'cm',min:10,max:100},
 {key:'armLeft',label:'Braço esquerdo',unit:'cm',min:10,max:100},
 {key:'thighRight',label:'Coxa direita (perna)',unit:'cm',min:15,max:150},
 {key:'thighLeft',label:'Coxa esquerda (perna)',unit:'cm',min:15,max:150}
];
function bodyMeasureValues(date=localDate()){return store.measures.find(m=>m.date===date)||{};}
function bodyFieldInput(f,m){return `<div class="form-field"><label for="measure-${f.key}">${f.label} (${f.unit})</label><input id="measure-${f.key}" name="${f.key}" type="number" min="${f.min}" max="${f.max}" step="0.1" value="${esc(m[f.key]??'')}" placeholder="Opcional" inputmode="decimal"></div>`;}
function populateBodyMeasurementDate(date){const m=bodyMeasureValues(date);for(const f of BODY_FIELDS){const input=document.getElementById('measure-'+f.key);if(input)input.value=m[f.key]??'';}}
function bodyFieldHistory(key){return store.measures.filter(m=>m[key]!==null&&m[key]!==undefined&&m[key]!==''&&Number(m[key])>0).sort((a,b)=>a.date.localeCompare(b.date));}
function latestMeasure(){if(!store.measures.length)return null;return Object.fromEntries(BODY_FIELDS.map(f=>[f.key,bodyFieldHistory(f.key).at(-1)?.[f.key]??null]));}
function bodyMeasureFollowup(){if(!store.measures.length)return 'Faça uma avaliação inicial e, se desejar, repita aproximadamente a cada quatro semanas. Não é preciso medir a cada treino.';const last=[...store.measures].sort((a,b)=>b.date.localeCompare(a.date))[0],days=Math.max(0,Math.floor((localDateFrom(localDate())-localDateFrom(last.date))/86400000));return days>=28?`Sua última avaliação foi em ${fmtDate(last.date)}. Já pode considerar uma nova medição, mantendo fita, ponto e horário semelhantes.`:`Última avaliação em ${fmtDate(last.date)}. Considere uma nova medição em aproximadamente ${28-days} dia(s), sem obrigação de medir toda semana.`;}

// Esta leitura integra dados observados; circunferencias nao diagnosticam composicao corporal.
function bodyAssessmentSnapshot(){
 const comparisons=BODY_FIELDS.map(field=>{const history=bodyFieldHistory(field.key);if(history.length<2)return null;const first=history[0],last=history.at(-1),elapsed=Math.max(0,Math.round((localDateFrom(last.date)-localDateFrom(first.date))/86400000));return {field,first,last,elapsed,delta:Number((Number(last[field.key])-Number(first[field.key])).toFixed(1))};}).filter(Boolean);
 const labels={definicao:'Definição muscular',forca:'Força e saúde',condicionamento:'Condicionamento'};
 const goal=store.profile.goal||'definicao';
 const today=localDate(),start=localDateFrom(today);start.setDate(start.getDate()-27);const cutoff=localDate(start);
 const recent=store.sessions.filter(s=>typeof s.date==='string'&&s.date>=cutoff&&s.date<=today);
 const complete=recent.filter(s=>['A','B','C'].includes(s.day)&&s.partial===false&&Number(s.doneSets)>0).length;
 const avulsos=recent.filter(s=>s.type==='avulso'||s.day==='AVULSO').length;
  const modalidades=recent.filter(s=>s.type==='modalidade').length;
 const training=`Nos últimos 28 dias, você registrou ${complete} ficha(s) A/B/C completas e ${avulsos} treino(s) avulso(s) de força, além de ${modalidades} atividade(s) de outras modalidades. A evolução das cargas, repetições, RIR e execução também deve orientar a revisão do treino.`;
 const waist=comparisons.find(x=>x.field.key==='waist');
 let reading='',status='',next='';
 if(!store.measures.length){status='Aguardando avaliação inicial';reading='Cadastre suas primeiras medidas para estabelecer seu ponto de partida. O app não inventa resultados quando não existem registros.';next='Registre peso e/ou circunferências que tiver disponíveis. Depois repita em condições semelhantes, preferencialmente após cerca de quatro semanas.';}
 else if(!comparisons.length){status='Linha de base registrada';reading='Você já tem uma avaliação inicial. Para interpretar uma evolução é necessário ter pelo menos duas medições da mesma região em datas diferentes.';next='Continue o plano conforme sua experiência, registro das séries e recuperação. Faça uma nova avaliação aproximadamente quatro semanas depois da inicial.';}
 else{
  status=comparisons.some(x=>x.elapsed>=21)?'Comparação disponível':'Comparação ainda recente';
  if(goal==='definicao'){
   if(!waist)reading='Seu objetivo é definição muscular. Já há circunferências comparáveis, mas a cintura ainda não possui duas medições. O peso, os treinos e a cintura medidos ao longo do tempo oferecem um acompanhamento mais completo.';
   else if(waist.elapsed<21)reading='Seu objetivo é definição muscular. As duas medidas de cintura estão próximas no tempo; acompanhe mais avaliações antes de tirar conclusões.';
   else if(waist.delta<0)reading=`Sua cintura reduziu ${fmtNum(Math.abs(waist.delta))} cm entre ${fmtDate(waist.first.date)} e ${fmtDate(waist.last.date)}. Isso confirma redução da circunferência medida, mas não comprova, isoladamente, perda de gordura. Compare também sua força, peso e regularidade.`;
   else if(waist.delta>0)reading=`Sua cintura aumentou ${fmtNum(waist.delta)} cm entre ${fmtDate(waist.first.date)} e ${fmtDate(waist.last.date)}. Confira se mediu no mesmo ponto e em condições parecidas; novas avaliações ajudarão a mostrar se há uma tendência.`;
   else reading='Sua cintura ficou com o mesmo valor entre as duas avaliações disponíveis. Isso, por si só, não define se o treino está ou não funcionando; acompanhe também execução, regularidade e as próximas medições.';
  }else if(goal==='forca'){
   reading='Seu objetivo é força e saúde. As diferenças de circunferência complementam a avaliação, mas o principal para revisar o treino será seu desempenho registrado: repetições, carga, RIR, técnica e recuperação. Centímetros a mais não comprovam hipertrofia.';
  }else{
   reading=`Seu objetivo é condicionamento. As medidas mostram mudanças de circunferência, mas não medem o fôlego. Nesta semana há ${cardioThisWeek()} minuto(s) de cardio registrado(s); compare também duração, intensidade percebida e recuperação, sem presumir atividades não lançadas.`;
  }
  next=comparisons.some(x=>x.elapsed<21)?'Há comparações feitas em um intervalo curto. Procure repetir as medições aproximadamente a cada quatro semanas, nos mesmos pontos e condições.':'Compare os mesmos pontos em novas avaliações e procure observar uma tendência em vez de decidir com base em uma medição isolada.';
 }
 const trainAdvice=complete<2?'O histórico recente ainda tem poucas fichas completas. Mantenha a prescrição compatível com sua fase, registre séries reais e discuta qualquer ajuste com o instrutor.':'Há sessões completas registradas. Para considerar progressão, confira desempenho consistente, técnica, esforço em reserva e recuperação; mudanças na fita métrica não alteram automaticamente séries ou cargas.';
 return {comparisons,goalLabel:labels[goal]||labels.definicao,status,reading,training,trainAdvice,next};
}
function bodyAssessmentMarkup(){const a=bodyAssessmentSnapshot(),observed=a.comparisons.length?a.comparisons.map(x=>`<li><strong>${esc(x.field.label)}:</strong> ${x.delta>0?'+':''}${fmtNum(x.delta)} ${x.field.unit} · ${fmtDate(x.first.date)} até ${fmtDate(x.last.date)} (${x.elapsed} dias)</li>`).join(''):'<li>Aguardando uma segunda medição da mesma região.</li>';return `<section id="body-assessment-section" class="body-assessment" aria-labelledby="body-assessment-title"><div class="eyebrow">INTERPRETAÇÃO DO ACOMPANHAMENTO</div><h3 id="body-assessment-title">Minha avaliação de evolução</h3><div class="body-assessment-meta"><span>Objetivo: ${esc(a.goalLabel)}</span><span>${esc(a.status)}</span></div><div class="body-assessment-part"><strong>O que suas medidas mostram</strong><p>${esc(a.reading)}</p><ul class="body-assessment-values">${observed}</ul></div><div class="body-assessment-part"><strong>O que isso significa para o treino</strong><p>${esc(a.training)} ${esc(a.trainAdvice)}</p></div><div class="body-assessment-part"><strong>Próximo acompanhamento</strong><p>${esc(a.next)}</p></div><p class="footnote">Leitura orientativa baseada exclusivamente no que você registrou no aparelho. Circunferências variam com medição, horário e outros fatores; não estimam isoladamente gordura, músculo ou condição clínica. O aplicativo não faz diagnóstico e não altera automaticamente séries ou cargas.</p></section>`;}
function bodyAssessmentTeaser(){const a=bodyAssessmentSnapshot();return `<div class="body-assessment-teaser"><strong>📊 Avaliação da evolução</strong><p>${esc(a.status)} · Objetivo: ${esc(a.goalLabel)}</p><p>${esc(a.reading)}</p><button class="btn outline block" data-action="go-measure">Ver análise e registrar medidas →</button></div>`;}
function measurementTrends(){const any=BODY_FIELDS.some(f=>bodyFieldHistory(f.key).length);return `<div class="body-trend"><h3>Comparação: primeira × última avaliação</h3><p class="footnote">As diferenças mostram apenas a mudança das medidas. Elas não indicam, isoladamente, ganho muscular, perda de gordura ou necessidade de aumentar séries.</p>${any?`<div class="body-trend-grid">${BODY_FIELDS.filter(f=>bodyFieldHistory(f.key).length).map(f=>{const arr=bodyFieldHistory(f.key),first=arr[0],last=arr.at(-1),delta=Number((Number(last[f.key])-Number(first[f.key])).toFixed(1)),different=arr.length>=2;return `<div class="body-trend-item"><strong>${esc(f.label)}</strong><span>${fmtNum(Number(last[f.key]))} ${f.unit} <small>mais recente</small></span><small>Inicial: ${fmtNum(Number(first[f.key]))} ${f.unit} · ${fmtDate(first.date)}</small><small>${different?`Variação: ${delta>0?'+':''}${fmtNum(delta)} ${f.unit} · até ${fmtDate(last.date)}`:'Aguardando nova medição para comparar'}</small></div>`;}).join('')}</div>`:'<p class="small muted">Nenhuma avaliação corporal cadastrada ainda.</p>'}<p class="footnote"><strong>Próxima avaliação:</strong> ${bodyMeasureFollowup()}</p></div>`;}
function measureHistory(){const a=[...store.measures].sort((x,y)=>y.date.localeCompare(x.date)).slice(0,8);return a.length?`<div style="margin-top:13px"><div class="eyebrow">REGISTROS MAIS RECENTES</div>${a.map(m=>`<div class="history-row"><div><strong>${fmtDate(m.date)}</strong><span>${BODY_FIELDS.filter(f=>m[f.key]!=null&&m[f.key]!==''&&Number(m[f.key])>0).map(f=>`${esc(f.label)}: ${fmtNum(Number(m[f.key]))} ${f.unit}`).join(' · ')||'Sem valores'}</span></div><button class="btn ghost smallbtn" data-action="remove-measure" data-id="${esc(m.id)}">Excluir</button></div>`).join('')}</div>`:'';}
function assessmentCard(){const p=store.profile,m=latestMeasure(),w=Number(m?.weight||p.weight),waist=Number(m?.waist||p.waist),height=Number(p.height),bmi=w&&height?w/((height/100)**2):null,additional=BODY_FIELDS.slice(2).filter(f=>m?.[f.key]!=null);return `<div class="card"><div class="grid-two"><div class="stat-mini"><b>${w?fmtNum(w)+' kg':'—'}</b><span>Peso mais recente</span></div><div class="stat-mini"><b>${waist?fmtNum(waist)+' cm':'—'}</b><span>Cintura abdominal</span></div><div class="stat-mini"><b>${height?height+' cm':'—'}</b><span>Altura</span></div><div class="stat-mini"><b>${bmi?fmtNum(bmi):'—'}</b><span>IMC orientativo</span></div></div>${additional.length?`<div class="body-latest"><strong>Outras medidas recentes</strong><div class="body-latest-grid">${additional.map(f=>`<span>${esc(f.label)}: <b>${fmtNum(Number(m[f.key]))} cm</b></span>`).join('')}</div></div>`:'<p class="footnote">Quer acompanhar braços, coxas e glúteos? Registre suas medidas na aba Evolução.</p>'}<p class="footnote" style="margin:12px 0 0">Faça as medições em condições parecidas. Circunferências e IMC, isoladamente, não definem composição corporal nem quantas séries fazer. O plano considera também experiência, treinos completos, duração e execução.</p></div>`;}
function goalAdvice(){return store.profile.goal==='condicionamento'?'Prioridade declarada: condicionamento. Inclua cardio moderado em dias alternados, avançando gradualmente à recomendação geral da OMS (150–300 min/semana).':store.profile.goal==='forca'?'Prioridade declarada: força e saúde. Progrida cargas com técnica e recuperação, sem buscar falha em todas as séries.':'Prioridade declarada: definição. Desenvolva força, preserve a regularidade e ajuste a alimentação com profissional; a cintura mostra tendência, não percentual de gordura.';}
function waterAmount(){return Math.max(0,Number(store.hydration?.[localDate()]||0));}
function waterCard(){return `<div class="card flat"><div class="water-head"><span style="font-size:27px">💧</span><div><strong>${fmtNum(waterAmount())} ml registrados</strong><p class="footnote" style="margin:2px 0 0">Registro de bebidas, não cálculo da necessidade total individual.</p></div></div><div class="pill-row" style="margin-top:11px"><button class="btn ghost smallbtn" data-action="water-add" data-ml="150">+150 ml</button><button class="btn teal smallbtn" data-action="water-add" data-ml="250">+250 ml</button><button class="btn outline smallbtn" data-action="water-undo">Desfazer 250 ml</button></div><p class="footnote" style="margin:10px 0 0">Adapte sua ingestão à sede, suor, ambiente e orientações clínicas. Evite consumir grandes volumes de uma vez.</p></div>`;}
function parseClock(val){const m=/^(\d{2}):(\d{2})$/.exec(String(val));return m?Number(m[1])*60+Number(m[2]):NaN;}
function reminderSlots(){const r=store.reminders;if(!r.enabled)return [];let slots=[];const start=parseClock(r.start),end=parseClock(r.end),step=Number(r.waterEvery)||120;if(r.water&&Number.isFinite(start)&&Number.isFinite(end)&&start<end){for(let minute=start;minute<=end;minute+=step)slots.push({key:'water-'+minute,minute,msg:'Hora de fazer uma pausa e considerar beber água 💧'});}for(const [type,time] of [['snackAM',r.snackAM],['snackPM',r.snackPM]])if(r.snack){let minute=parseClock(time);if(Number.isFinite(minute))slots.push({key:type,minute,msg:type==='snackAM'?'Pausa da manhã: avalie sua fome e escolha um lanche, se precisar. 🍎':'Pausa da tarde: se sentir fome, faça um lanche nutritivo. 🥛'});}return slots;}
function remindWhenOpen(){const now=new Date(),today=localDate(now),minute=now.getHours()*60+now.getMinutes();if(!store.reminders.enabled)return;const history=store.seenReminders[today]||(store.seenReminders[today]={});let changed=false;for(const slot of reminderSlots()){if(minute>=slot.minute&&minute<slot.minute+3&&!history[slot.key]){history[slot.key]=true;changed=true;notify(slot.msg);if(store.reminders.notifications && 'Notification' in window && Notification.permission==='granted'){try{new Notification('TRINCA 360',{body:slot.msg,icon:'assets/icon-192.png',tag:slot.key});}catch(e){}}}}if(changed)save();}
function icsDate(minute){return String(Math.floor(minute/60)).padStart(2,'0')+String(minute%60).padStart(2,'0')+'00';}
function exportReminders(){const slots=reminderSlots();if(!slots.length){notify('Ative os lembretes e escolha os horários primeiro.');return;}const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');const ymd=localDate().replace(/-/g,'');const escCal=x=>x.replace(/\\/g,'\\\\').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TRINCA360//AGENDA//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH'];slots.forEach((t,i)=>lines.push('BEGIN:VEVENT','UID:trinca360-'+t.key+'@local','DTSTAMP:'+stamp,'DTSTART:'+ymd+'T'+icsDate(t.minute),'RRULE:FREQ=DAILY','SUMMARY:'+escCal(t.key.startsWith('water')?'TRINCA 360 - Pausa para água':'TRINCA 360 - Pausa para lanche'),'DESCRIPTION:'+escCal(t.msg),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+escCal(t.msg),'TRIGGER:PT0M','END:VALARM','END:VEVENT'));lines.push('END:VCALENDAR');const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='TRINCA360_Lembretes_Calendario.ics';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Agenda .ics exportada. Importe no calendário e confirme os alertas no aparelho.');}

function nutritionPage(){const today=localDate(),h=store.habits[today]||{},habits=[['fresh','Baseei refeições em alimentos in natura/minimamente processados'],['produce','Incluí frutas, verduras ou legumes'],['protein','Distribuí fontes de proteína no dia'],['hydration','Observei minha hidratação e sede']];const total=habits.filter(([k])=>h[k]).length,weight=Number(latestMeasure()?.weight||store.profile.weight),veg=store.profile.foodStyle==='vegetariano';let meals=[['🌅','Café da manhã',veg?'Iogurte natural ou vegetal enriquecido + aveia + banana; alternativa: pão integral com pasta de grão-de-bico.':'Ovos + pão ou tapioca + uma fruta; alternativa: iogurte natural com aveia e banana.'],['☀️','Almoço',veg?'Arroz + feijão + tofu/omelete (se consumir) + salada colorida e legumes.':'Arroz + feijão + frango, peixe ou ovos + salada e legumes.'],['🍌','Lanche da tarde (se houver fome)',veg?'Fruta + castanhas; ou sanduíche de homus e tomate.':'Fruta + iogurte natural; ou pão com queijo e fruta.'],['🌙','Jantar',veg?'Sopa de legumes com lentilha; ou arroz, feijão e salada com tofu.':'Omelete com legumes e batata; ou refeição caseira com arroz, feijão e proteína.'],['🌜','Ceia opcional',veg?'Uma fruta, iogurte de sua preferência ou nada, se não houver fome.':'Leite/iogurte natural ou uma fruta, se sentir fome. Não é obrigatório.']];return `
  ${titleBlock('NUTRIÇÃO COM CIÊNCIA','Seu dia no prato.','Exemplos educativos, não prescrição clínica individual. Ajuste horários e porções com nutricionista.')}
  <section class="hero" style="background:#2C5B3C;min-height:195px"><div class="eyebrow">ENERGIA PARA EVOLUIR</div><h1 style="font-size:27px">Comida de verdade.<br>Treino consistente.</h1><p class="subtitle" style="margin-bottom:0">Sugestões de manhã, tarde e noite com alimentos acessíveis no Brasil.</p></section>
  <div class="section-heading"><h2>Exemplos de refeições</h2><button class="link-btn" data-action="go-profile">Preferências →</button></div>
  ${meals.map(([em,label,desc])=>`<div class="meal-card"><div class="meal-emoji">${em}</div><div><strong>${label}</strong><p>${desc}</p></div></div>`).join('')}
  <div class="notice info" style="margin-top:12px"><span>ℹ️</span><div>Não existe horário universal para comer. Lanches são opcionais conforme fome, treino e rotina. Não foram prescritas calorias ou porções com base apenas em peso/altura. ${store.profile.restrictions?'Você registrou restrições/preferências: '+esc(store.profile.restrictions)+'. Confira os ingredientes e procure orientação individual.':''}</div></div>
  <div class="section-heading"><h2>Água durante o dia</h2><span class="badge-date">Registro diário</span></div>${waterCard()}
  <div class="section-heading"><h2>Lembretes de água e lanches</h2></div><div class="card"><form id="reminders-form"><label class="checkbox-line"><input type="checkbox" name="enabled" ${store.reminders.enabled?'checked':''}> Ativar lembretes configurados</label><div class="grid-two" style="margin-top:16px"><label class="mini-field">Início das pausas de água<input type="time" name="start" required value="${esc(store.reminders.start)}"></label><label class="mini-field">Fim das pausas<input type="time" name="end" required value="${esc(store.reminders.end)}"></label></div><div class="form-field"><label>Intervalo de hidratação (lembrete, não obrigação de beber)</label><select name="waterEvery"><option value="120" ${Number(store.reminders.waterEvery)===120?'selected':''}>A cada 2 horas</option><option value="180" ${Number(store.reminders.waterEvery)===180?'selected':''}>A cada 3 horas</option></select></div><label class="checkbox-line"><input type="checkbox" name="water" ${store.reminders.water?'checked':''}> Lembrar pausas para água</label><label class="checkbox-line" style="margin:12px 0"><input type="checkbox" name="snack" ${store.reminders.snack?'checked':''}> Lembrar lanches opcionais</label><div class="grid-two"><label class="mini-field">Lanche manhã<input type="time" name="snackAM" required value="${esc(store.reminders.snackAM)}"></label><label class="mini-field">Lanche tarde<input type="time" name="snackPM" required value="${esc(store.reminders.snackPM)}"></label></div><button class="btn teal block" type="submit" style="margin-top:13px">Salvar lembretes</button></form><div class="stack" style="margin-top:12px"><button class="btn outline block" data-action="notification-permission">Permitir alertas enquanto o app estiver aberto</button><button class="btn outline block" data-action="export-reminders">↓ Gerar agenda recorrente (.ics)</button></div><p class="footnote" style="margin:12px 0 0"><strong>Transparência:</strong> avisos do navegador funcionam somente enquanto o aplicativo está aberto/ativo. Não há servidor de push nesta versão. Para lembretes com o app fechado, importe o arquivo .ics em um calendário compatível e habilite seus alertas; confirme no próprio calendário se a importação recorrente funcionou.</p></div>
  <div class="section-heading"><h2>Checklist de hoje</h2><span class="badge-date">${total} de 4 hábitos</span></div><div class="card flat"><div class="progress-track" style="margin-top:0"><div style="width:${total*25}%"></div></div>${habits.map(([id,name])=>`<label class="habit"><input type="checkbox" data-input="habit" data-id="${id}" ${h[id]?'checked':''}><span>${esc(name)}</span></label>`).join('')}</div>
  <div class="section-heading"><h2>Proteína e força</h2></div><div class="card"><p class="small muted">Para adultos saudáveis fisicamente ativos, a ISSN apresenta uma faixa geral de <strong>1,4–2,0 g/kg/dia</strong>, não uma meta obrigatória nem individual.</p><div class="notice info">${weight>=20&&weight<=350?`Com ${fmtNum(weight)} kg informados, a faixa matemática seria ${Math.round(weight*1.4)}–${Math.round(weight*2)} g/dia.`:'Adicione seu peso no Perfil para visualizar uma faixa matemática de referência.'}</div><p class="footnote">Doença renal, gravidez, tratamentos ou necessidades específicas requerem avaliação clínica. Não há necessidade automática de suplemento.</p></div>
  <div class="section-heading"><h2>Fontes e método</h2></div><div class="card">${DB.references.map(ref=>`<div class="source-item"><a href="${ref.url}" target="_blank" rel="noopener noreferrer">${esc(ref.name)} ↗</a><span>${esc(ref.org)} · ${esc(ref.tag)}</span></div>`).join('')}<p class="footnote">Base: diretrizes e literatura científica, não endosso pessoal de nutricionistas ou educadores físicos. A versão ${DB.version} não atualiza a ciência automaticamente.</p></div>`;}

function helpPage(){return `${titleBlock('CENTRAL DE AJUDA','Manual do TRINCA 360.','Um guia dentro do próprio aplicativo, do primeiro acesso ao registro da sua evolução.')}
 <div class="help-intro"><strong>Comece por aqui</strong><p>Preencha o Perfil, escolha seu treino e registre somente o que realmente realizou. Se foi uma sessão diferente, utilize Treino avulso.</p><div class="quick-actions"><button class="btn teal" data-action="go-profile">Abrir Perfil</button><button class="btn outline" data-action="go-avulso">Registrar avulso</button></div></div>
 <div class="help-topics">
 <details open><summary>1. Instalar no celular</summary><div class="help-copy"><p>No Android, abra este endereço no Chrome, toque em ⋮ e procure <strong>Instalar app</strong> ou <strong>Adicionar à tela inicial</strong>. Confirme e abra pelo ícone TRINCA 360. O ZIP é para desenvolvimento, não para uso cotidiano.</p><button class="btn ghost smallbtn" data-action="install">Ver instruções de instalação</button></div></details>
 <details open><summary>1.1. Compartilhar e instalar pelo QR Code</summary><div class="help-copy">
 <div class="share-app-section"><strong>Convide alguém para usar o TRINCA 360</strong><p>Mostre este QR Code na tela do seu celular. A outra pessoa aponta a câmera do celular dela, abre o link e instala o aplicativo com os próprios dados.</p>
 <div class="share-qr-wrap"><img class="share-qr-image" src="assets/trinca360-qr.svg" width="240" height="240" loading="eager" alt="QR Code do endereço https://gomes482.github.io/TRINCA360/ para instalar o TRINCA 360"></div>
 <p class="share-qr-caption">APONTE A CÂMERA PARA O QR CODE</p>
 <p class="share-url"><strong>Endereço oficial do app:</strong><br><a href="https://gomes482.github.io/TRINCA360/" target="_blank" rel="noopener noreferrer">https://gomes482.github.io/TRINCA360/</a></p>
 <div class="share-actions"><button type="button" class="btn outline" data-action="copy-share-url">Copiar link</button><a class="btn teal" href="https://gomes482.github.io/TRINCA360/" target="_blank" rel="noopener noreferrer">Abrir aplicativo ↗</a></div></div>
 <ol class="share-steps"><li>No celular da outra pessoa, escaneie o QR Code ou abra o link.</li><li>No Android, abra no Chrome e escolha ⋮ → Instalar app ou Adicionar à tela inicial; no iPhone, abra no Safari e use Compartilhar → Adicionar à Tela de Início.</li><li>Abra o TRINCA 360 e preencha o próprio Perfil, inclusive a data de início, o objetivo e a duração dos treinos.</li><li>Comece a registrar os treinos: os dados dessa pessoa ficam no navegador/aparelho dela.</li></ol>
 <p><strong>Privacidade:</strong> cada aparelho/navegador mantém seu próprio histórico local. Não existe conta na nuvem ou sincronização entre dispositivos. Não use o mesmo navegador/perfil de outra pessoa para criar históricos separados. Faça backup em Perfil regularmente.</p>
 </div></details>
 <details><summary>2. Preencher o Perfil e medir a cintura</summary><div class="help-copy"><p>Em Perfil, informe idade, peso, altura (cm), cintura (cm), nível de experiência, objetivo, data de início e duração desejada. Salve para calcular a fase atual. Meça a cintura com fita horizontal, sem apertar, no mesmo ponto nas próximas avaliações. Peso e medidas ajudam a acompanhar tendências, mas não definem cargas por si só.</p><button class="btn ghost smallbtn" data-action="go-profile">Abrir Perfil</button></div></details>
 <details><summary>3. Fazer as fichas A, B e C</summary><div class="help-copy"><p>Abra Treinos e escolha A, B ou C. Cada cartão informa quantas séries e repetições fazer. Marque S1, S2 etc. <strong>depois</strong> de executar cada série; registre carga e RIR (repetições que ainda conseguiria fazer com boa técnica). Use Como fazer para conferir a ilustração, instruções e vídeo externo. Ao terminar, toque em Registrar este treino e confirme tempo e cardio reais.</p><p>O modo de 30 minutos tem menos volume; em Perfil você pode escolher 45 ou 60 minutos. Não precisa chegar à falha muscular para progredir.</p><button class="btn ghost smallbtn" data-action="go-workouts">Abrir Treinos</button></div></details>
 <details><summary>4. Treinei peito + bíceps. Isso conta?</summary><div class="help-copy"><p><strong>Sim, quando você registrar.</strong> Escolha <strong>Treino avulso</strong>, marque Peito e Bíceps, informe os minutos reais de musculação e, se fez 10 minutos de esteira na mesma ida, coloque 10 em Cardio na mesma sessão. Isso adiciona uma sessão à frequência semanal e 10 minutos ao indicador de cardio, sem marcar A/B/C como concluídas.</p><p>O app não reconhece automaticamente atividades feitas fora dele. Não lance os mesmos 10 minutos novamente em Cardio extra.</p><button class="btn teal smallbtn" data-action="go-avulso">＋ Registrar treino avulso</button></div></details>
 <details><summary>4.1. Natação e outras modalidades</summary><div class="help-copy"><p>Abra <strong>Treinos → Treino avulso → Natação e outras atividades</strong>. Escolha Natação: a sugestão inicial será 45 minutos, mas registre a duração real. Pode lançar sábado e outros dias da semana, com datas próprias. Também existem corrida, caminhada, bicicleta, hidroginástica, dança, esportes, yoga, Pilates e Outra modalidade. O registro de natação conta no total de atividades e nos minutos de cardio informados, <strong>não</strong> na meta de musculação. Para modalidades com esforço variável, informe somente os minutos aeróbicos que souber identificar. Não lance a mesma atividade de novo em Cardio extra.</p><button class="btn teal smallbtn" data-action="go-avulso">Registrar natação ou modalidade</button></div></details><details><summary>5. Fiz só uma caminhada ou esteira</summary><div class="help-copy"><p>Vá em <strong>Evolução → Caminhadas e cardio extra</strong>, informe a data, a modalidade e os minutos. Isso soma ao cardio semanal, mas não cria uma sessão de musculação. Se você já registrou esses minutos dentro de outro treino, não repita.</p><button class="btn ghost smallbtn" data-action="go-progress">Abrir Evolução</button></div></details>
 <details><summary>6. Como acompanho séries, RIR e ciclos?</summary><div class="help-copy"><p>As cargas e séries marcadas ficam no histórico ao salvar. RIR 2 significa terminar a série com cerca de 2 repetições possíveis mantendo boa técnica. Nas semanas 1–2, iniciantes e pessoas retomando começam com 1 série; a partir da semana 3, o aumento de séries depende também de 3 dias distintos com fichas A/B/C completas. Para dicas de carga, registre o menor resultado entre as séries (por lado quando indicado), carga, RIR e execução. Só após duas sessões completas com mesma carga e desempenho consistente aparece uma sugestão para avaliar um pequeno aumento com o instrutor. O app nunca aumenta a carga automaticamente. A rotação é organizada em ciclos de 12 semanas.</p><button class="btn ghost smallbtn" data-action="go-progress">Meu histórico</button></div></details>
 <details><summary>7. Alimentação, água e lembretes</summary><div class="help-copy"><p>Na aba Nutrição há exemplos orientativos de café da manhã, almoço, lanches e jantar, inclusive alternativas vegetarianas. Não substituem uma prescrição individual de nutricionista. Registre água pelos botões +150 ml / +250 ml, conforme o que bebeu. Configure horários dos lembretes; os avisos internos funcionam enquanto o app estiver aberto e ativo. Para lembretes com ele fechado, exporte a agenda .ics e confira os alarmes no calendário em que a importar.</p><button class="btn ghost smallbtn" data-action="go-nutrition">Abrir Nutrição</button></div></details>
 <details><summary>8. Fazer avaliações físicas</summary><div class="help-copy"><p>Em Evolução, informe o peso e/ou cintura na data da medição. Tente comparar sempre nas mesmas condições. Observe também regularidade, fôlego, recuperação e cargas, não somente o peso.</p><button class="btn ghost smallbtn" data-action="go-progress">Registrar avaliação</button></div></details>
 <details><summary>8.1. Medir braços, coxas, glúteos e cintura</summary><div class="help-copy"><p>Em Evolução → Avaliação corporal, informe o peso (kg) e as circunferências em centímetros: cintura, glúteos/quadril (ponto de maior circunferência), braço direito/esquerdo e coxa direita/esquerda. Nenhuma medida é obrigatória isoladamente: preencha as que tiver, sempre com data real. Para comparar, use fita sem apertar, os mesmos pontos de referência e condições semelhantes; considere repetir aproximadamente a cada quatro semanas.</p><p>Você verá os últimos valores, a primeira medição e a variação em cm. A variação não representa automaticamente músculo ou gordura e <strong>não altera, sozinha, séries, repetições nem carga</strong>. Para revisar o treino, considere em conjunto as medidas, o objetivo, o histórico de treinos, a execução e a recuperação, preferencialmente com instrutor.</p><button class="btn ghost smallbtn" data-action="go-progress">Abrir avaliação corporal</button></div></details>
 <details><summary>8.2. Como o aplicativo avalia minhas medidas?</summary><div class="help-copy"><p>Em Evolução → Avaliação corporal, a seção Minha avaliação de evolução compara a primeira e a última medida disponível de cada região e informa as datas e diferenças. Ela usa o objetivo escolhido no Perfil e o número de fichas completas dos últimos 28 dias para dar uma leitura contextual. Para definição, observa também a cintura; para força, orienta comparar execução, carga e repetições; para condicionamento, considera o cardio registrado.</p><p>Uma única medição é apenas referência inicial. Medições próximas no tempo exigem cautela. A fita não determina percentual de gordura nem ganho muscular. A avaliação é informativa, não diagnóstico e não muda automaticamente séries ou cargas; confirme mudanças relevantes com um educador físico.</p><button class="btn ghost smallbtn" data-action="go-measure">Ver minha avaliação</button></div></details>
 <details><summary>9. Backup, atualização e privacidade</summary><div class="help-copy"><p>O histórico fica <strong>neste navegador/aparelho</strong>, não na página pública do GitHub. Em <strong>Perfil → Atualizações do aplicativo</strong>, toque em Verificar atualizações e, quando houver uma versão nova, em Aplicar atualização. <strong>Não precisa desinstalar.</strong> Finalize o treino antes de reiniciar. Em Perfil, exporte um backup .json regularmente e guarde-o em local privado. A opção Importar backup substitui os dados atuais. Não limpe os dados do site nem desinstale antes de exportar. Atualizações do código não sincronizam seus registros entre dispositivos. Vídeos externos precisam de internet.</p><button class="btn ghost smallbtn" data-action="go-updates">Ir às atualizações</button></div></details>
 <details><summary>9.1. Como manter a tela acesa durante o treino</summary><div class="help-copy"><p>Ao abrir uma ficha A, B ou C, o aplicativo tenta manter a tela acesa. Na ficha, use <strong>Permitir apagar a tela</strong> para desligar a proteção, e <strong>Manter tela acesa</strong> para reativá-la. Ao sair ou finalizar o treino, a proteção é liberada. Ao voltar do segundo plano, a proteção é solicitada novamente enquanto a ficha estiver aberta.</p><p>O recurso depende do navegador e pode ser interrompido pelo Android, por economia de bateria ou bloqueio manual. Não altera o brilho nem impede você de bloquear o aparelho pelo botão físico.</p><button class="btn ghost smallbtn" data-action="go-workouts">Abrir ficha de treino</button></div></details><details><summary>9.2. Alerta de fim do descanso (60 segundos)</summary><div class="help-copy"><p>Na ficha A, B ou C, ao marcar uma série concluída, o intervalo de 60 segundos começa automaticamente (exceto após a última série). Você também pode iniciar, pausar e reiniciar pelo relógio de Intervalo. Ao terminar, aparece um aviso sobre a tela inteira, com três toques sonoros suaves e vibração quando o dispositivo permitir. Se desejar, desligue em <strong>Som do descanso</strong>.</p><p>Toque em <strong>Próxima série</strong> para dispensar o alerta ou em <strong>Preciso de +30 segundos</strong> para ampliar a pausa. O relógio usa a hora real para recuperar o tempo caso o navegador atrase. O aviso visual funciona no aplicativo aberto; som e vibração podem não funcionar no segundo plano ou quando o Android restringe áudio. O tempo é uma referência: ajuste com o instrutor de acordo com exercício, intensidade e recuperação.</p><button class="btn ghost smallbtn" data-action="go-workouts">Abrir ficha de treino</button></div></details><details><summary>10. Segurança e limites do aplicativo</summary><div class="help-copy"><p>O TRINCA 360 é uma ferramenta de organização, não um monitor automático nem uma consulta médica ou nutricional. Não inventa repetições, intensidade, gasto calórico ou metas individuais. Peça ao educador físico para conferir a execução e adaptar os exercícios. Se sentir dor no peito, tontura importante ou falta de ar incomum, interrompa e procure avaliação apropriada.</p></div></details>
 </div><div class="help-outro">TRINCA 360 · versão ${DB.version}<br><strong>Desenvolvido por Anderson Gomes 🦫</strong></div>`;}

function profilePage(){const p=store.profile;return `${titleBlock('CONFIGURAÇÕES','O plano é seu.','Seu perfil, suas medidas e a duração do treino definem a proposta de progressão. Dados ficam neste navegador.')}
  <div class="card"><h3>Avaliação inicial e preferências</h3><form id="profile-form"><div class="form-field"><label for="p-name">Como quer ser chamado?</label><input id="p-name" type="text" name="name" maxlength="38" value="${esc(p.name)}" placeholder="Opcional"></div><div class="grid-two"><div class="form-field"><label for="p-age">Idade</label><input id="p-age" name="age" type="number" required min="18" max="100" value="${esc(p.age)}"></div><div class="form-field"><label for="p-weight">Peso (kg)</label><input id="p-weight" name="weight" type="number" min="20" max="350" step="0.1" value="${esc(p.weight)}" placeholder="Opcional"></div></div><div class="grid-two"><div class="form-field"><label for="p-height">Altura (cm)</label><input id="p-height" name="height" type="number" min="100" max="240" value="${esc(p.height)}" placeholder="Opcional"></div><div class="form-field"><label for="p-waist">Cintura (cm)</label><input id="p-waist" name="waist" type="number" min="30" max="220" step="0.1" value="${esc(p.waist||'')}" placeholder="Opcional"></div></div><div class="form-field"><label for="p-start">Início do programa (define as 12 semanas)</label><input id="p-start" type="date" name="startDate" max="${localDate()}" required value="${esc(p.startDate)}"></div><div class="form-field"><label for="p-level">Experiência com musculação</label><select name="experience" id="p-level"><option value="iniciante" ${p.experience==='iniciante'?'selected':''}>Nunca treinei / iniciante</option><option value="retomando" ${p.experience==='retomando'?'selected':''}>Retomando musculação</option><option value="ativo" ${p.experience==='ativo'?'selected':''}>Já treino regularmente</option></select></div><div class="form-field"><label for="p-goal">Objetivo principal</label><select name="goal" id="p-goal"><option value="definicao" ${p.goal==='definicao'?'selected':''}>Definição muscular</option><option value="condicionamento" ${p.goal==='condicionamento'?'selected':''}>Condicionamento</option><option value="forca" ${p.goal==='forca'?'selected':''}>Força e saúde</option></select></div><div class="form-field"><label for="p-duration">Quanto tempo você tem hoje?</label><select name="sessionLength" id="p-duration"><option value="30" ${p.sessionLength==='30'?'selected':''}>30 minutos — treino objetivo</option><option value="45" ${p.sessionLength==='45'?'selected':''}>45 minutos — 4 séries principais + 3 séries auxiliares</option><option value="60" ${p.sessionLength==='60'?'selected':''}>60 minutos — até 4 séries por exercício</option></select></div><div class="form-field"><label for="p-food">Preferência alimentar para exemplos de refeições</label><select name="foodStyle" id="p-food"><option value="geral" ${p.foodStyle==='geral'?'selected':''}>Geral (inclui alimentos de origem animal)</option><option value="vegetariano" ${p.foodStyle==='vegetariano'?'selected':''}>Vegetariana (com alternativas vegetais)</option></select></div><div class="form-field"><label for="p-restrictions">Alergias / restrições / cuidados (somente lembrete pessoal)</label><input name="restrictions" id="p-restrictions" maxlength="120" value="${esc(p.restrictions||'')}" placeholder="Ex.: não consumo lactose"></div><button class="btn teal block" type="submit">Salvar e ajustar meu plano</button></form><p class="footnote" style="margin:12px 0 0">O algoritmo adapta duração, ciclo, volume inicial e metas de esforço; peso, altura e cintura não determinam sozinhos uma prescrição segura. Para lesões, doenças, restrições ou dificuldades técnicas, peça avaliação profissional.</p></div>
  <div class="measure-shortcut"><div><strong>📏 Avaliação corporal completa</strong><p>Cadastrar peso, cintura, glúteos, braços e coxas e consultar o histórico.</p></div><button class="btn teal block" data-action="go-measure">Registrar minhas medidas →</button></div><div class="section-heading"><h2>Meu retrato atual</h2></div>${assessmentCard()}
  <div class="section-heading"><h2>Rotação em 12 semanas</h2></div><div class="card"><strong>Ciclo ${cycleNumber()} · Semana ${phaseWeek()}/12</strong><p class="small muted" style="margin-top:8px">${phaseTitle().title}. ${progressionNotice()} A cada 12 semanas o app alterna a seleção de exercícios e mantém seu histórico. A rotação é uma proposta de planejamento, não uma exigência fisiológica de trocar exercícios em data fixa. Reavalie seu progresso e consulte o instrutor.</p></div>
  <div id="updates-section" class="section-heading"><h2>Atualizações do aplicativo</h2></div>${updatesMarkup()}
  <div class="section-heading"><h2>Instalar no celular</h2></div><div class="install-note"><div class="grow"><strong>Seu atalho de treino</strong><p>Abra via HTTPS, adicione à tela inicial e acesse os treinos salvos.</p></div><button class="btn ghost smallbtn" data-action="install">Instalar</button></div>
  <div class="section-heading"><h2>Manual e ajuda</h2></div><div class="card flat"><p class="small muted">Consulte instalação, fichas A/B/C, treino avulso, cardio, Nutrição, medidas, RIR e backup.</p><button class="btn teal block" data-action="go-help">❔ Abrir manual completo</button></div><div class="section-heading"><h2>Meus dados e backup</h2></div><div class="card"><p class="small muted">Histórico da versão anterior é preservado neste mesmo navegador. Antes de trocar de dispositivo, exporte o backup. Não há conta ou sincronização automática entre aparelhos.</p><div class="stack"><button class="btn outline block" data-action="export">↓ Exportar backup (.json)</button><label class="btn outline block" style="cursor:pointer">↑ Importar backup <input id="import-input" type="file" accept=".json,application/json" hidden></label><button class="btn warn block" data-action="delete-all">Apagar meus registros</button></div></div><div class="section-heading"><h2>Créditos</h2></div><div class="card"><div class="author-mark">Desenvolvido por Anderson Gomes 🦫</div><p class="footnote">TRINCA 360 · versão ${DB.version}. Referências científicas na área Nutrição. Sem vínculo, revisão individual ou endosso das instituições citadas.</p></div>`;}

function exerciseModal(id,day=ui.day){const ex=DB.exercises[id];if(!ex)return;$('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="close" aria-label="Fechar" data-action="close-modal">×</button><div class="eyebrow">MOVIMENTO · ${esc(ex.group).toUpperCase()}</div><h2 id="modal-title">${esc(ex.name)}</h2><div class="pill-row"><span class="pill">${esc(ex.equipment)}</span><span class="pill gray">${setsFor(day,id)} × ${esc(repFor(id))}</span></div><img class="modal-hero" src="assets/exercises/${ex.image}.svg" alt="Desenho esquemático de ${esc(ex.name)}"><p class="footnote">Ilustração esquemática para reconhecimento; assista à demonstração para conferir o movimento.</p><h3>Execução passo a passo</h3><ol>${ex.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="tip"><strong>✓ Dica técnica: </strong>${esc(ex.tip)}</div><div class="care"><strong>⚠ Atenção: </strong>${esc(ex.care)}</div><a class="btn teal block" href="${ex.video}" target="_blank" rel="noopener noreferrer" style="margin-top:14px">▶ Abrir vídeo demonstrativo ↗</a><p class="footnote" style="margin:8px 0 0;text-align:center">Vídeo hospedado no site externo MuscleWiki; necessita conexão.</p></div></div>`;}
function finishModal(day){const d=draftFor(day),count=completedSets(day);if(!count){notify('Marque ao menos uma série antes de registrar.');return;}const defaultDuration=ui.sessionSeconds>0?Math.max(1,Math.round(ui.sessionSeconds/60)):Number(store.profile.sessionLength);$('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="finish-title"><button class="close" data-action="close-modal" aria-label="Fechar">×</button><div class="eyebrow">REGISTRO DA SESSÃO</div><h2 id="finish-title">Treino ${day} concluído?</h2><p class="small muted">Você marcou ${count} de ${targetSets(day)} séries. Confirme apenas o que realizou; registros parciais também contam no histórico.</p><form id="finish-form"><input type="hidden" name="day" value="${day}"><div class="form-field"><label for="finish-duration">Tempo realizado (minutos)</label><input id="finish-duration" name="duration" type="number" min="1" max="300" value="${defaultDuration}" required></div><div class="form-field"><label for="finish-cardio">Cardio efetivamente realizado (minutos)</label><input id="finish-cardio" name="cardio" type="number" min="0" max="300" value="0" required></div><div class="form-field"><label for="finish-note">Observação (opcional)</label><textarea id="finish-note" name="note" maxlength="300" placeholder="Como foi o treino?"></textarea></div><button class="btn teal block" type="submit">✓ Salvar meu treino</button></form></div></div>`;}
function genericModal(title,body,buttons=''){ $('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="generic-title"><button class="close" data-action="close-modal" aria-label="Fechar">×</button><h2 id="generic-title">${esc(title)}</h2><p class="small muted">${body}</p>${buttons}</div></div>`;}
function closeModal(){$('#dialog-root').innerHTML='';}
function toClock(sec){return `${String(Math.floor(Math.max(0,sec)/60)).padStart(2,'0')}:${String(Math.max(0,sec)%60).padStart(2,'0')}`;}
function doTick(){if(ui.sessionRunning)ui.sessionSeconds++;if(ui.restRunning){ui.restSeconds=Math.max(0,Math.ceil((restDeadline-Date.now())/1000));if(ui.restSeconds===0)showRestFinished();}const s=$('#clock-session'),r=$('#clock-rest');if(s)s.textContent=toClock(ui.sessionSeconds);if(r)r.textContent=toClock(ui.restSeconds);}
function render(){const main=$('#app-main');if(!main)return;main.innerHTML=ui.page==='home'?home():ui.page==='workouts'?workoutPage():ui.page==='progress'?progressPage():ui.page==='nutrition'?nutritionPage():ui.page==='help'?helpPage():ui.page==='avulso'?avulsoPage():profilePage();document.querySelectorAll('[data-nav]').forEach(b=>{const sel=b.dataset.nav===ui.page;b.classList.toggle('active',sel);if(sel)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const badge=$('#network-pill');if(badge){badge.textContent=navigator.onLine?'● Online':'● Offline';badge.classList.toggle('offline',!navigator.onLine);}}
function confirmDelete(){genericModal('Apagar todos os registros?','Isso removerá seus treinos, medidas, caminhadas, perfil e hábitos deste navegador. Se quiser preservar algo, exporte um backup antes.','<div class="stack"><button class="btn warn block" data-action="delete-confirm">Sim, apagar tudo</button><button class="btn outline block" data-action="close-modal">Cancelar</button></div>');}
function exportData(){const blob=new Blob([JSON.stringify({app:'TRINCA360',schema:1,exportedAt:new Date().toISOString(),data:store},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Trinca360_backup_${localDate()}.json`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);notify('Backup exportado. Guarde em local seguro.');}
function validImport(data){return data&&data.app==='TRINCA360'&&data.schema===1&&data.data&&typeof data.data==='object'&&data.data.profile&&Array.isArray(data.data.sessions)&&Array.isArray(data.data.measures)&&Array.isArray(data.data.walks)&&data.data.sessions.length<20000&&data.data.measures.length<20000&&data.data.walks.length<20000;}
function install(){if(ui.installPrompt){ui.installPrompt.prompt();ui.installPrompt.userChoice.then(()=>ui.installPrompt=null);return;}genericModal('Como instalar no celular','O aplicativo deve estar publicado em um endereço HTTPS (por exemplo, GitHub Pages). No Android, abra no Chrome e use ⋮ > Adicionar à tela inicial ou Instalar app. No iPhone, use Compartilhar > Adicionar à Tela de Início. Arquivos abertos diretamente do ZIP não podem ser instalados como PWA.','<button class="btn teal block" data-action="close-modal">Entendi</button>');}
function handleClick(ev){const a=ev.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id,day=a.dataset.day,index=Number(a.dataset.index);if(action==='close-modal'){if(ev.target.classList.contains('modal-scrim')||a.classList.contains('close')||a.dataset.action==='close-modal'&&a.tagName==='BUTTON')closeModal();return;}switch(action){case 'rest-alert-dismiss':closeRestAlert();ui.restSeconds=60;render();break;case 'rest-alert-extra':startRest(30);break;case 'rest-sound-toggle':store.restSound=store.restSound===false;save();if(store.restSound!==false)prepareRestAudio();render();notify(store.restSound===false?'Som do intervalo desativado.':'Som do intervalo ativado.');break;case 'toggle-screen-wake':if(screenWakeRequested&&screenWakeLock&&!screenWakeLock.released)stopScreenWake();else{screenWakeRequested=true;requestScreenWake();}break;case 'go-updates':setNav('profile');setTimeout(()=>$('#updates-section')?.scrollIntoView({behavior:'smooth',block:'start'}),40);break;case 'check-updates':checkForUpdates(true);break;case 'apply-update':applyAppUpdate();break;case 'copy-share-url':{const url='https://gomes482.github.io/TRINCA360/';if(navigator.clipboard?.writeText){navigator.clipboard.writeText(url).then(()=>notify('Link copiado! Compartilhe com quem quiser instalar o TRINCA 360.')).catch(()=>window.prompt('Copie o link do aplicativo:',url));}else window.prompt('Copie o link do aplicativo:',url);break;}case 'go-measure':setNav('progress');setTimeout(()=>$('#measure-section')?.scrollIntoView({behavior:'smooth',block:'start'}),60);break;case 'scroll-measure':$('#measure-section')?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'go-help':setNav('help');break;case 'go-avulso':setNav('avulso');break;case 'go-progress':setNav('progress');break;case 'go-profile':setNav('profile');break;case 'go-workouts':setNav('workouts');break;case 'go-nutrition':setNav('nutrition');break;case 'water-add':store.hydration[localDate()]=waterAmount()+Number(a.dataset.ml);save();render();notify('Água registrada!');break;case 'water-undo':store.hydration[localDate()]=Math.max(0,waterAmount()-250);save();render();break;case 'export-reminders':exportReminders();break;case 'notification-permission':if(!('Notification' in window)){notify('Alertas do navegador indisponíveis neste aparelho.');break;}Notification.requestPermission().then(v=>{store.reminders.notifications=v==='granted';save();notify(v==='granted'?'Alertas permitidos enquanto o app estiver aberto.':'Use a agenda .ics para lembretes externos.');});break;case 'open-day':setDay(day);break;case 'exercise-detail':exerciseModal(id,day||ui.day);break;case 'set-toggle':{const d=draftFor(day);d[id].sets[index]=!d[id].sets[index];save();if(d[id].sets[index]&&completedSets(day)<targetSets(day)){startRest(60);}else{if(completedSets(day)>=targetSets(day))stopRest();render();}break;}case 'session-toggle':ui.sessionRunning=!ui.sessionRunning;render();if(ui.sessionRunning&&!screenWakeRequested){screenWakeRequested=true;requestScreenWake(true);}break;case 'session-reset':ui.sessionRunning=false;ui.sessionSeconds=0;render();break;case 'rest-toggle':if(ui.restRunning){pauseRest();render();}else startRest(ui.restSeconds>0?ui.restSeconds:60);break;case 'rest-reset':stopRest();render();break;case 'finish-start':stopRest();finishModal(day);break;case 'install':install();break;case 'export':exportData();break;case 'delete-all':confirmDelete();break;case 'delete-confirm':{stopRest();stopScreenWake(true);store=structuredClone(DEFAULTS);save();ui.day='A';ui.sessionRunning=false;ui.sessionSeconds=0;closeModal();setNav('home');notify('Registros apagados deste aparelho.');break;}case 'remove-cardio':{if(confirm('Excluir este registro de cardio extra?')){store.walks=store.walks.filter(w=>String(w.id)!==String(id));save();render();notify('Cardio extra excluído.');}break;}case 'remove-measure':{if(confirm('Excluir esta avaliação?')){store.measures=store.measures.filter(m=>m.id!==id);save();render();notify('Avaliação excluída.');}break;}}}
function submitHandler(e){const form=e.target;if(!['profile-form','measure-form','walk-form','finish-form','reminders-form','avulso-form','modality-form'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);if(form.id==='reminders-form'){if(parseClock(f.get('start'))>=parseClock(f.get('end'))){notify('O fim do período deve ser depois do início.');return;}store.reminders={...store.reminders,enabled:!!f.get('enabled'),water:!!f.get('water'),snack:!!f.get('snack'),start:String(f.get('start')),end:String(f.get('end')),waterEvery:Number(f.get('waterEvery')),snackAM:String(f.get('snackAM')),snackPM:String(f.get('snackPM'))};save();render();notify('Horários de lembretes salvos.');return;}if(form.id==='profile-form'){const age=Number(f.get('age')),startDate=String(f.get('startDate'));if(!(age>=18&&age<=100)||startDate>localDate()){notify('Revise idade e data de início.');return;}store.profile={name:String(f.get('name')).trim().slice(0,38),age,weight:String(f.get('weight')),height:String(f.get('height')),waist:String(f.get('waist')),experience:String(f.get('experience')),goal:String(f.get('goal')),sessionLength:String(f.get('sessionLength')),foodStyle:String(f.get('foodStyle')),restrictions:String(f.get('restrictions')).trim().slice(0,120),startDate};save();render();notify('Perfil salvo!');return;}
if(form.id==='measure-form'){
 const date=String(f.get('date'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||Number.isNaN(localDateFrom(date).getTime())||localDate(localDateFrom(date))!==date){notify('Confira a data da avaliação.');return;}
 const values={};for(const field of BODY_FIELDS){const raw=String(f.get(field.key)??'').trim(),num=Number(raw.replace(',','.'));if(raw!==''&&(!Number.isFinite(num)||num<field.min||num>field.max)){notify('Revise a medida de '+field.label+' ('+field.unit+').');return;}values[field.key]=raw===''?null:num;}
 if(!BODY_FIELDS.some(field=>values[field.key]!=null)){notify('Informe ao menos uma medida para salvar.');return;}
 const old=store.measures.find(m=>m.date===date),previous=[...store.measures];store.measures=store.measures.filter(m=>m.date!==date);store.measures.push({...old,id:old?.id||(crypto.randomUUID?crypto.randomUUID():String(Date.now())),date,...values});
 if(!save()){store.measures=previous;return;}render();$('#body-assessment-section')?.scrollIntoView({behavior:'smooth',block:'start'});notify('Avaliação salva! Veja a interpretação logo abaixo.');return;
}
if(form.id==='walk-form'){const date=String(f.get('date')),minutes=Number(f.get('minutes'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||minutes<1||minutes>600||!Number.isInteger(minutes)){notify('Confira data e minutos.');return;}store.walks.push({id:`cardio-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,date,minutes,type:String(f.get('type')||'Cardio').slice(0,40)});save();render();notify('Cardio independente registrado!');return;}
if(form.id==='modality-form'){const date=String(f.get('date')),modality=String(f.get('modality')),entry=ACTIVITY_TYPES.find(x=>x.name===modality),name=modality==='Outra modalidade'?String(f.get('other')||'').trim().slice(0,55):modality,duration=Number(f.get('duration')),cardio=Number(f.get('cardio'));if(!entry||!name||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||Number.isNaN(localDateFrom(date).getTime())||localDate(localDateFrom(date))!==date||!Number.isInteger(duration)||duration<1||duration>600||!Number.isInteger(cardio)||cardio<0||cardio>duration){notify('Revise modalidade, data e minutos realizados (aeróbico não supera a duração).');return;}const effort=String(f.get('effort')||'Não informado'),allowed=['Não informado','Leve','Moderado','Vigoroso'];if(!allowed.includes(effort)){notify('Confira o esforço informado.');return;}const note=String(f.get('note')||'').trim().slice(0,300);store.sessions.push({id:`modality-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type:'modalidade',date,day:'MODALIDADE',modality:name,activityGroup:entry.kind,durationMin:duration,strengthMin:0,cardioMin:cardio,effort,note,partial:false,doneSets:null,exercises:{}});if(!save()){store.sessions.pop();return;}setNav('progress');notify(name+' registrado(a): '+duration+' minutos, sem duplicidade!');return;}
if(form.id==='avulso-form'){const date=String(f.get('date')),groups=f.getAll('groups').map(String).filter(g=>['Peito','Costas','Bíceps','Tríceps','Pernas','Ombros','Abdômen','Glúteos','Corpo inteiro','Outro'].includes(g)),strength=Number(f.get('strength')),cardio=Number(f.get('cardio'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||!groups.length||!Number.isInteger(strength)||strength<1||strength>300||!Number.isInteger(cardio)||cardio<0||cardio>300||strength+cardio>300){notify('Marque um grupo e confira data e minutos (total até 300).');return;}const note=String(f.get('note')||'').trim().slice(0,300),kind=String(f.get('cardioType')||'Esteira').slice(0,40);store.sessions.push({id:`avulso-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type:'avulso',date,day:'AVULSO',groups:[...new Set(groups)],strengthMin:strength,cardioMin:cardio,cardioType:cardio?kind:null,durationMin:strength+cardio,doneSets:null,partial:false,note,exercises:{}});if(!save()){store.sessions.pop();return;}setNav('progress');notify('Treino avulso e cardio registrado(s) sem duplicidade!');return;}
if(form.id==='finish-form'){const day=String(f.get('day')),durationMin=Number(f.get('duration')),cardioMin=Number(f.get('cardio'));if(!DB.programs[day]||!Number.isFinite(durationMin)||durationMin<1||durationMin>300||!Number.isFinite(cardioMin)||cardioMin<0||cardioMin>durationMin){notify('Confira a duração e o cardio (não pode superar a sessão).');return;}const d=draftFor(day),sets=Object.fromEntries(program(day).exercises.map(id=>[id,{setsDone:d[id].sets.slice(0,setsFor(day,id)).filter(Boolean).length,weight:d[id].weight||null,rir:d[id].rir===''?null:Number(d[id].rir),planned:setsFor(day,id),reps:repFor(id),repsDone:d[id].repsDone?Number(d[id].repsDone):null,technique:d[id].technique||null}])),doneSets=completedSets(day),partial=doneSets<targetSets(day);store.sessions.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,date:localDate(),day,durationMin,cardioMin,note:String(f.get('note')).slice(0,300),doneSets,partial,cycle:cycleNumber(),week:phaseWeek(),durationMode:store.profile.sessionLength,exercises:sets});delete store.drafts[day];stopRest();stopScreenWake(true);ui.sessionRunning=false;ui.sessionSeconds=0;ui.restRunning=false;ui.restSeconds=store.profile.sessionLength==='30'?60:90;save();closeModal();setNav('progress');notify(partial?'Treino parcial registrado.':'Treino completo registrado!');return;}}
function handleInput(e){const t=e.target;if(t.dataset.input==='rir'){draftFor(t.dataset.day)[t.dataset.id].rir=t.value;save();}if(t.dataset.input==='weight'){const v=t.value;const day=t.dataset.day,id=t.dataset.id;const num=Number(v);if(v!==''&&(!Number.isFinite(num)||num<0||num>500)){notify('Informe uma carga entre 0 e 500 kg.');return;}draftFor(day)[id].weight=v;save();}if(t.dataset.input==='reps-done'){const d=draftFor(t.dataset.day)[t.dataset.id],v=t.value,n=Number(v);if(v!==''&&(!Number.isInteger(n)||n<1||n>90)){notify('Informe um número inteiro de 1 a 90.');return;}d.repsDone=v;save();}if(t.dataset.input==='technique'){draftFor(t.dataset.day)[t.dataset.id].technique=t.value;save();}if(t.dataset.input==='habit'){const date=localDate(),id=t.dataset.id;if(!store.habits[date])store.habits[date]={};store.habits[date][id]=t.checked;save();render();}}
async function importFile(file){if(!file)return;try{if(file.size>5_000_000){notify('Backup grande demais (máx. 5 MB).');return;}const obj=JSON.parse(await file.text());if(!validImport(obj)){notify('Arquivo não é um backup TRINCA 360 válido.');return;}if(!confirm('Importar substituirá TODOS os registros atuais deste navegador. Deseja continuar?'))return;const data=obj.data;store={...structuredClone(DEFAULTS),...data,profile:{...DEFAULTS.profile,...data.profile},drafts:data.drafts&&typeof data.drafts==='object'?data.drafts:{},habits:data.habits&&typeof data.habits==='object'?data.habits:{},hydration:data.hydration&&typeof data.hydration==='object'?data.hydration:{},reminders:{...DEFAULTS.reminders,...(data.reminders||{})},seenReminders:data.seenReminders&&typeof data.seenReminders==='object'?data.seenReminders:{}};save();setNav('home');notify('Backup importado com sucesso!');}catch(e){notify('Não foi possível ler este backup.');}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();ui.installPrompt=e;});
window.addEventListener('online',render);window.addEventListener('offline',render);
document.addEventListener('click',handleClick);
document.addEventListener('submit',submitHandler);
document.addEventListener('change',e=>{if(e.target.id==='mod-kind')syncModalityForm(true);if(e.target.id==='mod-duration')syncModalityForm(false);if(e.target.id==='mod-cardio')e.target.dataset.auto='no';handleInput(e);if(e.target.id==='measure-date')populateBodyMeasurementDate(e.target.value);if(e.target.id==='import-input')importFile(e.target.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(restAlertVisible){closeRestAlert();ui.restSeconds=60;render();}else closeModal();}});
document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{setNav(b.dataset.nav);if(b.dataset.nav==='workouts'&&!screenWakeRequested){screenWakeRequested=true;requestScreenWake(true);}}));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(screenWakeRequested&&ui.page==='workouts')requestScreenWake(true);doTick();if(restAlertVisible)playRestAlarm();}});
window.addEventListener('pagehide',()=>{stopRest();stopScreenWake(true);});
if('serviceWorker' in navigator&&window.isSecureContext)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA indisponível',e)));
tickId=setInterval(doTick,1000);setInterval(remindWhenOpen,30000);remindWhenOpen();
window.addEventListener('load',()=>setTimeout(()=>checkForUpdates(false),1800));
window.addEventListener('online',()=>{if(updateState.status==='offline')checkForUpdates(false);});

render();
})();
